public class DurableDataChangeMonitoredItemQueue : IDataChangeMonitoredItemQueue, IDisposable
{
	private const uint kBatchSize = 1000u;

	private DataChangeBatch m_enqueueBatch;

	private readonly List<DataChangeBatch> m_dataChangeBatches = new List<DataChangeBatch>();

	private DataChangeBatch m_dequeueBatch;

	private bool m_queueErrors;

	private readonly IBatchPersistor m_batchPersistor;

	private readonly ILogger m_logger;

	/// <inheritdoc />
	public uint MonitoredItemId { get; }

	/// <summary>
	/// Gets the current queue size.
	/// </summary>
	public uint QueueSize { get; private set; }

	/// <summary>
	/// Gets number of elements actually contained in value queue.
	/// </summary>
	public int ItemsInQueue { get; private set; }

	/// <inheritdoc />
	public bool IsDurable { get; }

	/// <summary>
	/// Invoked when the queue is disposed
	/// </summary>
	public event EventHandler Disposed;

	/// <summary>
	/// Creates an empty queue.
	/// </summary>
	public DurableDataChangeMonitoredItemQueue(bool createDurable, uint monitoredItemId, IBatchPersistor batchPersistor, ITelemetryContext telemetry)
	{
		IsDurable = createDurable;
		MonitoredItemId = monitoredItemId;
		m_logger = TelemetryExtensions.CreateLogger<DurableDataChangeMonitoredItemQueue>(telemetry);
		m_batchPersistor = batchPersistor;
		m_enqueueBatch = new DataChangeBatch(new List<(DataValue, ServiceResult)>(), 1000u, monitoredItemId);
		m_dequeueBatch = m_enqueueBatch;
		QueueSize = 0u;
		ItemsInQueue = 0;
	}

	/// <summary>
	/// Creates a queue from a template
	/// </summary>
	public DurableDataChangeMonitoredItemQueue(StorableDataChangeQueue queue, IBatchPersistor batchPersistor)
	{
		m_batchPersistor = batchPersistor;
		MonitoredItemId = queue.MonitoredItemId;
		IsDurable = queue.IsDurable;
		m_enqueueBatch = queue.EnqueueBatch;
		m_dequeueBatch = queue.DequeueBatch;
		m_dataChangeBatches = queue.DataChangeBatches;
		QueueSize = queue.QueueSize;
		ItemsInQueue = queue.ItemsInQueue;
	}

	/// <summary>
	/// Brings the queue with content into a storable format
	/// </summary>
	public StorableDataChangeQueue ToStorableQueue()
	{
		return new StorableDataChangeQueue
		{
			IsDurable = IsDurable,
			MonitoredItemId = MonitoredItemId,
			QueueSize = QueueSize,
			ItemsInQueue = ItemsInQueue,
			DataChangeBatches = m_dataChangeBatches,
			DequeueBatch = m_dequeueBatch,
			EnqueueBatch = m_enqueueBatch
		};
	}

	/// <summary>
	/// Adds the value to the queue.
	/// </summary>
	/// <param name="value">The value to queue.</param>
	/// <param name="error">The error to queue.</param>
	/// <exception cref="T:System.InvalidOperationException"></exception>
	public void Enqueue(DataValue value, ServiceResult error)
	{
		if (QueueSize == 0)
		{
			throw new InvalidOperationException("Cannot enqueue Value. Queue size not set.");
		}
		if (ItemsInQueue == QueueSize)
		{
			Dequeue(out DataValue _, out ServiceResult _);
		}
		m_enqueueBatch.Values.Add((value, m_queueErrors ? error : null));
		ItemsInQueue++;
		HandleEnqueueBatching();
	}

	/// <summary>
	/// persists batches if needed
	/// </summary>
	private void HandleEnqueueBatching()
	{
		if ((long)m_enqueueBatch.Values.Count < 1000L)
		{
			return;
		}
		if (m_dequeueBatch == m_enqueueBatch)
		{
			m_dequeueBatch = new DataChangeBatch(m_enqueueBatch.Values, 1000u, MonitoredItemId);
			m_enqueueBatch = new DataChangeBatch(new List<(DataValue, ServiceResult)>(), 1000u, MonitoredItemId);
			return;
		}
		m_logger.LogDebug("Storing batch for monitored item {MonitoredItemId}", MonitoredItemId);
		DataChangeBatch item = new DataChangeBatch(m_enqueueBatch.Values, 1000u, MonitoredItemId);
		m_dataChangeBatches.Add(item);
		if (m_dataChangeBatches.Count > 1)
		{
			IBatchPersistor batchPersistor = m_batchPersistor;
			List<DataChangeBatch> dataChangeBatches = m_dataChangeBatches;
			batchPersistor.RequestBatchPersist(dataChangeBatches[dataChangeBatches.Count - 2]);
		}
		m_enqueueBatch = new DataChangeBatch(new List<(DataValue, ServiceResult)>(), 1000u, MonitoredItemId);
	}

	/// <inheritdoc />
	public void OverwriteLastValue(DataValue value, ServiceResult error)
	{
		if (ItemsInQueue == 0)
		{
			throw new InvalidOperationException("Cannot overwrite Value. Queue is empty.");
		}
		if (m_enqueueBatch.Values.Count > 0)
		{
			List<(DataValue, ServiceResult)> values = m_enqueueBatch.Values;
			values[values.Count - 1] = (value, error);
		}
		else if (m_dataChangeBatches.Count > 0)
		{
			List<DataChangeBatch> dataChangeBatches = m_dataChangeBatches;
			List<(DataValue, ServiceResult)> values2 = dataChangeBatches[dataChangeBatches.Count - 1].Values;
			values2[values2.Count - 1] = (value, error);
		}
		else
		{
			List<(DataValue, ServiceResult)> values3 = m_dequeueBatch.Values;
			values3[values3.Count - 1] = (value, error);
		}
	}

	/// <inheritdoc />
	public void ResetQueue(uint queueSize, bool queueErrors)
	{
		m_enqueueBatch = new DataChangeBatch(new List<(DataValue, ServiceResult)>(), 1000u, MonitoredItemId);
		m_dequeueBatch = m_enqueueBatch;
		ItemsInQueue = 0;
		m_queueErrors = queueErrors;
		QueueSize = queueSize;
		foreach (DataChangeBatch dataChangeBatch in m_dataChangeBatches)
		{
			m_batchPersistor.DeleteBatch(dataChangeBatch);
		}
		m_dataChangeBatches.Clear();
	}

	/// <inheritdoc />
	public DataValue PeekLastValue()
	{
		if (ItemsInQueue == 0)
		{
			return null;
		}
		if (m_enqueueBatch.Values.Count > 0)
		{
			List<(DataValue, ServiceResult)> values = m_enqueueBatch.Values;
			return values[values.Count - 1].Item1;
		}
		if (m_dataChangeBatches.Count > 0)
		{
			List<DataChangeBatch> dataChangeBatches = m_dataChangeBatches;
			List<(DataValue, ServiceResult)> values2 = dataChangeBatches[dataChangeBatches.Count - 1].Values;
			return values2[values2.Count - 1].Item1;
		}
		List<(DataValue, ServiceResult)> values3 = m_dequeueBatch.Values;
		return values3[values3.Count - 1].Item1;
	}

	/// <inheritdoc />
	public bool Dequeue(out DataValue value, out ServiceResult error)
	{
		value = null;
		error = null;
		if (ItemsInQueue == 0)
		{
			return false;
		}
		if (m_dequeueBatch.IsPersisted)
		{
			m_logger.LogDebug("Dequeue was requeusted but queue was not restored for monitoreditem {MonitoredItemId} try to restore for 10 ms.", MonitoredItemId);
			m_batchPersistor.RequestBatchRestore(m_dequeueBatch);
			if (!SpinWait.SpinUntil(() => !m_dequeueBatch.RestoreInProgress, 10))
			{
				m_logger.LogDebug("Dequeue failed for monitoreditem {MonitoredItemId} as queue could not be restored in time.", MonitoredItemId);
				return false;
			}
		}
		(value, error) = m_dequeueBatch.Values[0];
		m_dequeueBatch.Values.RemoveAt(0);
		ItemsInQueue--;
		HandleDequeBatching();
		return true;
	}

	/// <summary>
	/// Restores batches if needed
	/// </summary>
	private void HandleDequeBatching()
	{
		if ((long)m_dequeueBatch.Values.Count <= 500L && m_dataChangeBatches.Count > 0)
		{
			m_batchPersistor.RequestBatchRestore(m_dataChangeBatches[0]);
		}
		if (m_dequeueBatch.Values.Count != 0 || m_dequeueBatch == m_enqueueBatch)
		{
			return;
		}
		if (m_dataChangeBatches.Count > 0)
		{
			m_dequeueBatch = m_dataChangeBatches[0];
			m_dataChangeBatches.RemoveAt(0);
			if (m_dataChangeBatches.Count > 0)
			{
				m_batchPersistor.RequestBatchRestore(m_dataChangeBatches[0]);
			}
		}
		else
		{
			m_dequeueBatch = m_enqueueBatch;
		}
	}

	/// <inheritdoc />
	public DataValue PeekOldestValue()
	{
		if (ItemsInQueue == 0)
		{
			return null;
		}
		return m_dequeueBatch.Values[0].Item1;
	}

	/// <inheritdoc />
	public void Dispose()
	{
		Dispose(disposing: true);
		GC.SuppressFinalize(this);
	}

	/// <summary>
	/// An overrideable version of the Dispose.
	/// </summary>
	protected virtual void Dispose(bool disposing)
	{
		if (disposing)
		{
			Disposed?.Invoke(this, EventArgs.Empty);
		}
	}
}
/// <summary>
/// Batch of Datachanges and corresponding errors
/// </summary>
public class DataChangeBatch : BatchBase
{
	public List<(DataValue, ServiceResult)> Values { get; set; }

	public DataChangeBatch(List<(DataValue, ServiceResult)> values, uint batchSize, uint monitoredItemId)
		: base(batchSize, monitoredItemId)
	{
		Values = values;
	}

	public override void SetPersisted()
	{
		Values = null;
		base.IsPersisted = true;
		base.PersistingInProgress = false;
	}

	public void Restore(List<(DataValue, ServiceResult)> values)
	{
		Values = values;
		base.IsPersisted = false;
		base.RestoreInProgress = false;
	}
}
