		protected virtual void Dispose(bool disposing)
		{
			if (m_disposed)
			{
				return;
			}
			if (disposing)
			{
				if (m_factory != null)
				{
					m_factory.Dispose();
					m_factory = null;
				}
				if (m_server != null)
				{
					try
					{
						Disconnect();
					}
					catch
					{
					}
					m_server = null;
				}
			}
			m_disposed = true;
		}

