		public virtual void Connect(URL url, ConnectData connectData)
		{
			if (url == null)
			{
				throw new ArgumentNullException("url");
			}
			if (m_server != null)
			{
				throw new AlreadyConnectedException();
			}
			SetUrl(url);
			try
			{
				m_server = m_factory.CreateInstance(url, connectData);
				m_connectData = connectData;
				GetSupportedLocales();
				SetLocale(m_locale);
			}
			catch (Exception ex)
			{
				if (m_server != null)
				{
					try
					{
						Disconnect();
					}
					catch
					{
					}
				}
				throw ex;
			}
		}

		public virtual void Disconnect()
		{
			if (m_server == null)
			{
				throw new NotConnectedException();
			}
			m_server.Dispose();
			m_server = null;
		}

		public virtual Server Duplicate()
		{
			Server obj = (Server)Activator.CreateInstance(GetType(), m_factory, m_url);
			obj.m_connectData = m_connectData;
