	[Serializable]
	public class URL : ICloneable
	{
		private string m_scheme;

		private string m_hostName;

		private int m_port;

		private string m_path;

		public string Scheme
		{
			get
			{
				return m_scheme;
			}
			set
			{
				m_scheme = value;
			}
		}

		public string HostName
		{
			get
			{
				return m_hostName;
			}
			set
			{
				m_hostName = value;
			}
		}

		public int Port
		{
			get
			{
				return m_port;
			}
			set
			{
				m_port = value;
			}
		}

		public string Path
		{
			get
			{
				return m_path;
			}
			set
			{
				m_path = value;
			}
		}

		public URL()
		{
			Scheme = "http";
			HostName = "localhost";
			Port = 0;
			Path = null;
		}

		public URL(string url)
		{
			Scheme = "http";
			HostName = "localhost";
			Port = 0;
			Path = null;
			string text = url;
			int num = text.IndexOf("://");
			if (num >= 0)
			{
				Scheme = text.Substring(0, num);
				text = text.Substring(num + 3);
			}
			num = text.IndexOfAny(new char[1] { '/' });
			if (num < 0)
			{
				Path = text;
				return;
			}
			string text2 = text.Substring(0, num);
			IPAddress iPAddress;
			try
			{
				iPAddress = IPAddress.Parse(text2);
			}
			catch
			{
				iPAddress = null;
			}
			if (iPAddress != null && iPAddress.AddressFamily == AddressFamily.InterNetworkV6)
			{
				if (text2.Contains("]"))
				{
					HostName = text2.Substring(0, text2.IndexOf("]") + 1);
					if (text2.Substring(text2.IndexOf(']')).Contains(":"))
					{
						string text3 = text2.Substring(text2.LastIndexOf(':') + 1);
						if (text3 != "")
						{
							try
							{
								Port = System.Convert.ToUInt16(text3);
							}
							catch
							{
								Port = 0;
							}
						}
						else
						{
							Port = 0;
						}
					}
					else
					{
						Port = 0;
					}
					Path = text.Substring(num + 1);
				}
				else
				{
					HostName = "[" + text2 + "]";
					Port = 0;
				}
				Path = text.Substring(num + 1);
				return;
			}
			num = text.IndexOfAny(new char[2] { ':', '/' });
			if (num < 0)
			{
				Path = text;
				return;
			}
			HostName = text.Substring(0, num);
			if (text[num] == ':')
			{
				text = text.Substring(num + 1);
				num = text.IndexOf("/");
				string value;
				if (num >= 0)
				{
					value = text.Substring(0, num);
					text = text.Substring(num + 1);
				}
				else
				{
					value = text;
					text = "";
				}
				try
				{
					Port = System.Convert.ToUInt16(value);
				}
				catch
				{
					Port = 0;
				}
			}
			else
			{
				text = text.Substring(num + 1);
			}
			Path = text;
		}

		public override string ToString()
		{
			string text = ((HostName == null || HostName == "") ? "localhost" : HostName);
			if (Port > 0)
			{
				return $"{Scheme}://{text}:{Port}/{Path}";
			}
			return string.Format("{0}://{1}/{2}", new object[3] { Scheme, text, Path });
		}

		public override bool Equals(object target)
		{
			URL uRL = null;
			if (target != null && target.GetType() == typeof(URL))
			{
				uRL = (URL)target;
			}
			if (target != null && target.GetType() == typeof(string))
			{
				uRL = new URL((string)target);
			}
			if (uRL != null && !(uRL.Path != Path) && !(uRL.Scheme != Scheme) && !(uRL.HostName != HostName))
			{
				return uRL.Port == Port;
			}
			return false;
		}

		public override int GetHashCode()
		{
			return ToString().GetHashCode();
		}

		public virtual object Clone()
		{
			return MemberwiseClone();
		}
	}
