	[Serializable]
	public class Time
	{
		private DateTime m_absoluteTime = DateTime.MinValue;

		private RelativeTime m_baseTime;

		private TimeOffsetCollection m_offsets = new TimeOffsetCollection();

		public bool IsRelative
		{
			get
			{
				return m_absoluteTime == DateTime.MinValue;
			}
			set
			{
				m_absoluteTime = DateTime.MinValue;
			}
		}

		public DateTime AbsoluteTime
		{
			get
			{
				return m_absoluteTime;
			}
			set
			{
				m_absoluteTime = value;
			}
		}

		public RelativeTime BaseTime
		{
			get
			{
				return m_baseTime;
			}
			set
			{
				m_baseTime = value;
			}
		}

		public TimeOffsetCollection Offsets => m_offsets;

		public Time()
		{
		}

		public Time(DateTime time)
		{
			AbsoluteTime = time;
		}

		public Time(string time)
		{
			Time time2 = Parse(time);
			m_absoluteTime = DateTime.MinValue;
			m_baseTime = time2.m_baseTime;
			m_offsets = time2.m_offsets;
		}

		public DateTime ResolveTime()
		{
			if (!IsRelative)
			{
				return m_absoluteTime;
			}
			DateTime utcNow = DateTime.UtcNow;
			int year = utcNow.Year;
			int month = utcNow.Month;
			int day = utcNow.Day;
			int hour = utcNow.Hour;
			int minute = utcNow.Minute;
			int second = utcNow.Second;
			int millisecond = utcNow.Millisecond;
			switch (BaseTime)
			{
			case RelativeTime.Second:
				millisecond = 0;
				break;
			case RelativeTime.Minute:
				second = 0;
				millisecond = 0;
				break;
			case RelativeTime.Hour:
				minute = 0;
				second = 0;
				millisecond = 0;
				break;
			case RelativeTime.Day:
			case RelativeTime.Week:
				hour = 0;
				minute = 0;
				second = 0;
				millisecond = 0;
				break;
			case RelativeTime.Month:
				day = 0;
				hour = 0;
				minute = 0;
				second = 0;
				millisecond = 0;
				break;
			case RelativeTime.Year:
				month = 0;
				day = 0;
				hour = 0;
				minute = 0;
				second = 0;
				millisecond = 0;
				break;
			}
			utcNow = new DateTime(year, month, day, hour, minute, second, millisecond);
			if (BaseTime == RelativeTime.Week && utcNow.DayOfWeek != DayOfWeek.Sunday)
			{
				utcNow = utcNow.AddDays(0.0 - (double)utcNow.DayOfWeek);
			}
			foreach (TimeOffset offset in Offsets)
			{
				switch (offset.Type)
				{
				case RelativeTime.Second:
					utcNow = utcNow.AddSeconds(offset.Value);
					break;
				case RelativeTime.Minute:
					utcNow = utcNow.AddMinutes(offset.Value);
					break;
				case RelativeTime.Hour:
					utcNow = utcNow.AddHours(offset.Value);
					break;
				case RelativeTime.Day:
					utcNow = utcNow.AddDays(offset.Value);
					break;
				case RelativeTime.Week:
					utcNow = utcNow.AddDays(offset.Value * 7);
					break;
				case RelativeTime.Month:
					utcNow = utcNow.AddMonths(offset.Value);
					break;
				case RelativeTime.Year:
					utcNow = utcNow.AddYears(offset.Value);
					break;
				}
			}
			return utcNow;
		}

		public override string ToString()
		{
			if (!IsRelative)
			{
				return Convert.ToString(m_absoluteTime);
			}
			StringBuilder stringBuilder = new StringBuilder(256);
			stringBuilder.Append(BaseTypeToString(BaseTime));
			stringBuilder.Append(Offsets.ToString());
			return stringBuilder.ToString();
		}

		public static Time Parse(string buffer)
		{
			buffer = buffer.Trim();
			Time time = new Time();
			bool flag = false;
			foreach (RelativeTime value in Enum.GetValues(typeof(RelativeTime)))
			{
				string text = BaseTypeToString(value);
				if (buffer.StartsWith(text))
				{
					buffer = buffer.Substring(text.Length).Trim();
					time.BaseTime = value;
					flag = true;
					break;
				}
			}
			if (!flag)
			{
				time.AbsoluteTime = System.Convert.ToDateTime(buffer).ToUniversalTime();
				return time;
			}
			if (buffer.Length > 0)
			{
				time.Offsets.Parse(buffer);
			}
			return time;
		}

		private static string BaseTypeToString(RelativeTime baseTime)
		{
			return baseTime switch
			{
				RelativeTime.Now => "NOW", 
				RelativeTime.Second => "SECOND", 
				RelativeTime.Minute => "MINUTE", 
				RelativeTime.Hour => "HOUR", 
				RelativeTime.Day => "DAY", 
				RelativeTime.Week => "WEEK", 
				RelativeTime.Month => "MONTH", 
				RelativeTime.Year => "YEAR", 
				_ => throw new ArgumentOutOfRangeException("baseTime", baseTime.ToString(), "Invalid value for relative base time."), 
			};
		}
	}
	[Serializable]
	public struct TimeOffset
	{
		private int m_value;

		private RelativeTime m_type;

		public int Value
		{
			get
			{
				return m_value;
			}
			set
			{
				m_value = value;
			}
		}

		public RelativeTime Type
		{
			get
			{
				return m_type;
			}
			set
			{
				m_type = value;
			}
		}

		internal static string OffsetTypeToString(RelativeTime offsetType)
		{
			return offsetType switch
			{
				RelativeTime.Second => "S", 
				RelativeTime.Minute => "M", 
				RelativeTime.Hour => "H", 
				RelativeTime.Day => "D", 
				RelativeTime.Week => "W", 
				RelativeTime.Month => "MO", 
				RelativeTime.Year => "Y", 
				_ => throw new ArgumentOutOfRangeException("offsetType", offsetType.ToString(), "Invalid value for relative time offset type."), 
			};
		}
	}
	[Serializable]
	public class TimeOffsetCollection : ArrayList
	{
		public new TimeOffset this[int index]
		{
			get
			{
				return this[index];
			}
			set
			{
				this[index] = value;
			}
		}

		public int Add(int value, RelativeTime type)
		{
			return base.Add(new TimeOffset
			{
				Value = value,
				Type = type
			});
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder(256);
			foreach (TimeOffset item in (IEnumerable)this)
			{
				if (item.Value >= 0)
				{
					stringBuilder.Append("+");
				}
				stringBuilder.AppendFormat("{0}", item.Value);
				stringBuilder.Append(TimeOffset.OffsetTypeToString(item.Type));
			}
			return stringBuilder.ToString();
		}

		public void Parse(string buffer)
		{
			Clear();
			bool positive = true;
			int num = 0;
			string text = "";
			int num2 = 0;
			for (int i = 0; i < buffer.Length; i++)
			{
				if (buffer[i] == '+' || buffer[i] == '-')
				{
					if (num2 == 3)
					{
						Add(CreateOffset(positive, num, text));
						num = 0;
						text = "";
						num2 = 0;
					}
					if (num2 != 0)
					{
						throw new FormatException("Unexpected token encountered while parsing relative time string.");
					}
					positive = buffer[i] == '+';
					num2 = 1;
				}
				else if (char.IsDigit(buffer, i))
				{
					if (num2 == 3)
					{
						Add(CreateOffset(positive, num, text));
						num = 0;
						text = "";
						num2 = 0;
					}
					if (num2 != 0 && num2 != 1 && num2 != 2)
					{
						throw new FormatException("Unexpected token encountered while parsing relative time string.");
					}
					num *= 10;
					num += System.Convert.ToInt32(buffer[i] - 48);
					num2 = 2;
				}
				else if (!char.IsWhiteSpace(buffer, i))
				{
					if (num2 != 2 && num2 != 3)
					{
						throw new FormatException("Unexpected token encountered while parsing relative time string.");
					}
					text += buffer[i];
					num2 = 3;
				}
			}
			if (num2 == 3)
			{
				Add(CreateOffset(positive, num, text));
				num2 = 0;
			}
			if (num2 != 0)
			{
				throw new FormatException("Unexpected end of string encountered while parsing relative time string.");
			}
		}

		public void CopyTo(TimeOffset[] array, int index)
		{
			CopyTo(array, index);
		}

		public void Insert(int index, TimeOffset value)
		{
			Insert(index, value);
		}

		public void Remove(TimeOffset value)
		{
			Remove(value);
		}

		public bool Contains(TimeOffset value)
		{
			return Contains(value);
		}

		public int IndexOf(TimeOffset value)
		{
			return IndexOf(value);
		}

		public int Add(TimeOffset value)
		{
			return Add(value);
		}

		private static TimeOffset CreateOffset(bool positive, int magnitude, string units)
		{
			foreach (RelativeTime value in Enum.GetValues(typeof(RelativeTime)))
			{
				if (value != RelativeTime.Now && units == TimeOffset.OffsetTypeToString(value))
				{
					return new TimeOffset
					{
						Value = (positive ? magnitude : (-magnitude)),
						Type = value
					};
				}
			}
			throw new ArgumentOutOfRangeException("units", units, "String is not a valid offset time type.");
		}
	}
