			{
				m_items[index] = value;
			}
		}

		public Item this[ItemIdentifier itemID]
		{
			get
			{
				foreach (Item item in m_items)
				{
					if (itemID.Key == item.Key)
					{
						return item;
					}
				}
				return null;
			}
		}

		public bool IsSynchronized => false;

		public int Count
		{
			get
			{
				if (m_items == null)
				{
					return 0;
				}
				return m_items.Count;
			}
