				for (int j = 0; j < array.Length; j++)
				{
					if (item.ServerHandle.Equals(items[j].ServerHandle))
					{
						flag = array[j].ResultID.Succeeded();
						break;
					}
				}
				if (!flag)
				{
					arrayList.Add(item);
