				}
				int num3 = num;
				byte b = ((bitOffset == 0) ? byte.MaxValue : ((byte)((128 >> bitOffset - 1) - 1)));
				int num4 = 0;
				while (num3 >= 0 && num4 < num2)
				{
					int num5 = context.Index + num4;
					buffer[num5] += (byte)((b & ((1 << num3) - 1) & array[num4]) << (int)bitOffset);
					if (num3 + bitOffset <= 8)
