					object current = enumerator.Current;
					if (i == field.ElementCount)
					{
						break;
					}
					int num = WriteField(context, field, fieldIndex, fieldValues, current, ref bitOffset);
					if (num == 0 && bitOffset == 0)
					{
						break;
					}
					context.Index += num;
					i++;
				}
				for (; i < field.ElementCount; i++)
				{
					int num2 = WriteField(context, field, fieldIndex, fieldValues, null, ref bitOffset);
					if (num2 == 0 && bitOffset == 0)
					{
						break;
					}
					context.Index += num2;
				}
			}
			else if (field.ElementCountRef != null)
			{
				int num3 = 0;
				foreach (object item in array)
				{
					int num4 = WriteField(context, field, fieldIndex, fieldValues, item, ref bitOffset);
					if (num4 == 0 && bitOffset == 0)
					{
						break;
					}
					context.Index += num4;
					num3++;
				}
				WriteReference(context, field, fieldIndex, fieldValues, field.ElementCountRef, num3);
			}
			else if (field.FieldTerminator != null)
			{
				foreach (object item2 in array)
				{
					int num5 = WriteField(context, field, fieldIndex, fieldValues, item2, ref bitOffset);
					if (num5 == 0 && bitOffset == 0)
					{
						break;
					}
					context.Index += num5;
				}
				byte[] terminator = GetTerminator(context, field);
				if (context.Buffer != null)
				{
					for (int j = 0; j < terminator.Length; j++)
					{
						context.Buffer[context.Index + j] = terminator[j];
					}
				}
				context.Index += terminator.Length;
			}
			if (bitOffset != 0)
			{
				context.Index++;
			}
			return context.Index - index;
		}

		private void WriteReference(Context context, FieldType field, int fieldIndex, ComplexValue[] fieldValues, string fieldName, int count)
		{
			ComplexValue complexValue = null;
			if (fieldName.Length == 0)
			{
				if (fieldIndex > 0 && fieldIndex - 1 < fieldValues.Length)
				{
					complexValue = fieldValues[fieldIndex - 1];
				}
			}
			else
			{
				for (int i = 0; i < fieldIndex; i++)
				{
					complexValue = fieldValues[i];
					if (complexValue.Name == fieldName)
					{
						break;
					}
					complexValue = null;
				}
			}
			if (complexValue == null)
			{
				throw new InvalidSchemaException("Referenced field not found (" + fieldName + ").");
			}
			if (context.Buffer == null)
			{
				complexValue.Value = count;
			}
			if (!count.Equals(complexValue.Value))
			{
				throw new InvalidDataToWriteException("Reference field value and the actual array length are not equal.");
			}
		}
