				browseFilters.ElementNameFilter = filterName;
				browseFilters.BrowseFilter = browseFilter.item;
				browseFilters.ReturnAllProperties = false;
				browseFilters.PropertyIDs = CPX_PROPERTIES;
				browseFilters.ReturnPropertyValues = true;
				OpcDaNetApi.Da.BrowseElement[] array2 = server.Browse(m_filterItem, browseFilters, out position);
				if (array2 == null || array2.Length == 0)
				{
					throw new ApplicationException("Could not browse to new data filter.");
				}
				ComplexItem complexItem = new ComplexItem();
				if (!complexItem.Init(array2[0]))
				{
					throw new ApplicationException("Could not initialize to new data filter.");
				}
				return complexItem;
			}
			finally
			{
				if (position != null)
				{
					position.Dispose();
					position = null;
				}
			}
		}

		public void UpdateDataFilter(OpcDaNetApi.Da.Server server, string filterValue)
		{
			if (m_unfilteredItemID == null)
			{
				throw new ApplicationException("Cannot update the data filter for this item.");
			}
			IdentifiedResult[] array = server.Write(new OpcDaNetApi.Da.ItemValue[1]
			{
				new OpcDaNetApi.Da.ItemValue(this)
				{
					Value = filterValue,
					Quality = OpcDaNetApi.Da.Quality.Bad,
					QualitySpecified = false,
					Timestamp = DateTime.MinValue,
					TimestampSpecified = false
				}
			});
			if (array == null || array.Length == 0)
			{
				throw new ApplicationException("Unexpected result from server.");
			}
			if (array[0].ResultID.Failed())
			{
				throw new ApplicationException("Could not update data filter.");
			}
			m_filterValue = filterValue;
		}

		public string GetTypeDictionary(OpcDaNetApi.Da.Server server)
		{
			ItemPropertyCollection[] properties = server.GetProperties(new ItemIdentifier[1] { m_dictionaryItemID }, new PropertyID[1] { Property.DICTIONARY }, returnValues: true);
			if (properties == null || properties.Length == 0 || properties[0].Count == 0)
			{
				return null;
			}
			ItemProperty itemProperty = properties[0][0];
			if (!itemProperty.ResultID.Succeeded())
			{
				return null;
			}
			return (string)itemProperty.Value;
		}

		public string GetTypeDescription(OpcDaNetApi.Da.Server server)
		{
			ItemPropertyCollection[] properties = server.GetProperties(new ItemIdentifier[1] { m_typeItemID }, new PropertyID[1] { Property.TYPE_DESCRIPTION }, returnValues: true);
			if (properties == null || properties.Length == 0 || properties[0].Count == 0)
			{
				return null;
			}
			ItemProperty itemProperty = properties[0][0];
			if (!itemProperty.ResultID.Succeeded())
			{
				return null;
			}
			return (string)itemProperty.Value;
		}

		public void GetDataFilterItem(OpcDaNetApi.Da.Server server)
		{
			m_filterItem = null;
			if (m_unfilteredItemID != null)
			{
				return;
			}
			OpcDaNetApi.Da.BrowsePosition position = null;
			try
			{
				ItemIdentifier itemID = new ItemIdentifier(this);
				BrowseFilters browseFilters = new BrowseFilters();
				browseFilters.ElementNameFilter = "DataFilters";
				browseFilters.BrowseFilter = browseFilter.all;
				browseFilters.ReturnAllProperties = false;
				browseFilters.PropertyIDs = null;
				browseFilters.ReturnPropertyValues = false;
				OpcDaNetApi.Da.BrowseElement[] array;
				if (m_unconvertedItemID == null)
				{
					browseFilters.ElementNameFilter = "CPX";
					array = server.Browse(itemID, browseFilters, out position);
					if (array == null || array.Length == 0)
					{
						return;
					}
					if (position != null)
					{
						position.Dispose();
						position = null;
					}
					itemID = new ItemIdentifier(array[0].ItemPath, array[0].ItemName);
					browseFilters.ElementNameFilter = "DataFilters";
				}
				array = server.Browse(itemID, browseFilters, out position);
				if (array != null && array.Length != 0)
				{
					m_filterItem = new ItemIdentifier(array[0].ItemPath, array[0].ItemName);
				}
			}
			finally
			{
				if (position != null)
				{
					position.Dispose();
					position = null;
				}
			}
		}

		private void Clear()
		{
			m_typeSystemID = null;
			m_dictionaryID = null;
			m_typeID = null;
			m_dictionaryItemID = null;
			m_typeItemID = null;
			m_unconvertedItemID = null;
			m_unfilteredItemID = null;
			m_filterItem = null;
			m_filterValue = null;
		}

		private bool Init(OpcDaNetApi.Da.BrowseElement element)
		{
			base.ItemPath = element.ItemPath;
			base.ItemName = element.ItemName;
			m_name = element.Name;
			return Init(element.Properties);
		}

		private bool Init(ItemProperty[] properties)
		{
			Clear();
			if (properties == null || properties.Length < 3)
			{
				return false;
			}
			foreach (ItemProperty itemProperty in properties)
			{
				if (itemProperty.ResultID.Succeeded())
				{
					if (itemProperty.ID == Property.TYPE_SYSTEM_ID)
					{
						m_typeSystemID = (string)itemProperty.Value;
					}
					else if (itemProperty.ID == Property.DICTIONARY_ID)
					{
						m_dictionaryID = (string)itemProperty.Value;
						m_dictionaryItemID = new ItemIdentifier(itemProperty.ItemPath, itemProperty.ItemName);
					}
					else if (itemProperty.ID == Property.TYPE_ID)
					{
						m_typeID = (string)itemProperty.Value;
						m_typeItemID = new ItemIdentifier(itemProperty.ItemPath, itemProperty.ItemName);
					}
					else if (itemProperty.ID == Property.UNCONVERTED_ITEM_ID)
					{
						m_unconvertedItemID = new ItemIdentifier(base.ItemPath, (string)itemProperty.Value);
					}
					else if (itemProperty.ID == Property.UNFILTERED_ITEM_ID)
					{
						m_unfilteredItemID = new ItemIdentifier(base.ItemPath, (string)itemProperty.Value);
					}
					else if (itemProperty.ID == Property.DATA_FILTER_VALUE)
					{
						m_filterValue = (string)itemProperty.Value;
					}
				}
			}
			if (m_typeSystemID != null && m_dictionaryID != null)
			{
				return m_typeID != null;
			}
			return false;
		}
	}
	public class ComplexTypeCache
	{
		private static OpcDaNetApi.Da.Server m_server = null;

		private static Hashtable m_items = new Hashtable();

		private static Hashtable m_dictionaries = new Hashtable();

		private static Hashtable m_descriptions = new Hashtable();

		public static OpcDaNetApi.Da.Server Server
		{
			get
			{
				lock (typeof(ComplexTypeCache))
				{
					return m_server;
				}
			}
			set
			{
				lock (typeof(ComplexTypeCache))
				{
					m_server = value;
					m_items.Clear();
					m_dictionaries.Clear();
					m_descriptions.Clear();
				}
			}
		}

		public static ComplexItem GetComplexItem(ItemIdentifier itemID)
		{
			if (itemID == null)
			{
				return null;
			}
			lock (typeof(ComplexTypeCache))
			{
				ComplexItem complexItem = new ComplexItem(itemID);
				try
				{
					complexItem.Update(m_server);
				}
				catch
				{
					complexItem = null;
				}
				m_items[itemID.Key] = complexItem;
				return complexItem;
			}
		}

		public static ComplexItem GetComplexItem(OpcDaNetApi.Da.BrowseElement element)
		{
			if (element == null)
			{
				return null;
			}
			lock (typeof(ComplexTypeCache))
			{
				return GetComplexItem(new ItemIdentifier(element.ItemPath, element.ItemName));
			}
		}

		public static string GetTypeDictionary(ItemIdentifier itemID)
		{
			if (itemID == null)
			{
				return null;
			}
			lock (typeof(ComplexTypeCache))
			{
				string text = (string)m_dictionaries[itemID.Key];
				if (text != null)
				{
					return text;
				}
				ComplexItem complexItem = GetComplexItem(itemID);
				if (complexItem != null)
				{
					text = complexItem.GetTypeDictionary(m_server);
				}
				return text;
			}
		}

		public static string GetTypeDescription(ItemIdentifier itemID)
		{
			if (itemID == null)
			{
				return null;
			}
			lock (typeof(ComplexTypeCache))
			{
				string result = null;
				ComplexItem complexItem = GetComplexItem(itemID);
				if (complexItem != null)
				{
					result = (string)m_descriptions[complexItem.TypeItemID.Key];
					if (result != null)
					{
						return result;
					}
					object obj = (m_descriptions[complexItem.TypeItemID.Key] = complexItem.GetTypeDescription(m_server));
					result = (string)obj;
				}
				return result;
			}
		}
	}
