namespace OpcDaNetApiCom
{
	public class ConnectionPoint : IDisposable
	{
		private OpcDaComRcw.Comn.IConnectionPoint m_server;

		private int m_cookie;

		private int m_refs;

		public int Cookie => m_cookie;

		public ConnectionPoint(object server, Guid iid)
		{
			((OpcDaComRcw.Comn.IConnectionPointContainer)server).FindConnectionPoint(ref iid, out m_server);
		}

		public void Dispose()
		{
			if (m_server != null)
			{
				while (Unadvise() > 0)
				{
				}
				Interop.ReleaseServer(m_server);
				m_server = null;
			}
		}

		public int Advise(object callback)
		{
			if (m_refs++ == 0)
			{
				m_server.Advise(callback, out m_cookie);
			}
			return m_refs;
		}

		public int Unadvise()
		{
			if (--m_refs == 0)
			{
				m_server.Unadvise(m_cookie);
			}
			return m_refs;
		}
	}
	public class EnumGuid
	{
		private IEnumGUID m_enumerator;

		public EnumGuid(object server)
		{
			m_enumerator = (IEnumGUID)server;
		}

		public void Release()
		{
			Interop.ReleaseServer(m_enumerator);
			m_enumerator = null;
		}

		public object GetEnumerator()
		{
			return m_enumerator;
		}

		public Guid[] GetAll()
		{
			Reset();
			ArrayList arrayList = new ArrayList();
			while (true)
			{
				Guid[] array = Next(1);
				if (array == null)
				{
					break;
				}
				arrayList.AddRange(array);
			}
			return (Guid[])arrayList.ToArray(typeof(Guid));
		}

		public Guid[] Next(int count)
		{
			nint num = Marshal.AllocCoTaskMem(Marshal.SizeOf(typeof(Guid)) * count);
			try
			{
				int pceltFetched = 0;
				try
				{
					m_enumerator.Next(count, num, out pceltFetched);
				}
				catch (Exception)
				{
					return null;
				}
				if (pceltFetched == 0)
				{
					return null;
				}
				nint ptr = num;
				Guid[] array = new Guid[pceltFetched];
				for (int i = 0; i < pceltFetched; i++)
				{
					array[i] = (Guid)Marshal.PtrToStructure(ptr, typeof(Guid));
					ptr = (nint)(((IntPtr)ptr).ToInt64() + Marshal.SizeOf(typeof(Guid)));
				}
				return array;
			}
			finally
			{
				Marshal.FreeCoTaskMem(num);
			}
		}

		public void Skip(int count)
		{
			m_enumerator.Skip(count);
		}

		public void Reset()
		{
			m_enumerator.Reset();
		}

		public EnumGuid Clone()
		{
			IEnumGUID ppenum = null;
			m_enumerator.Clone(out ppenum);
			return new EnumGuid(ppenum);
		}
	}
	public class EnumString : IDisposable
	{
		private OpcDaComRcw.Comn.IEnumString m_enumerator;

		public EnumString(object enumerator)
		{
			m_enumerator = (OpcDaComRcw.Comn.IEnumString)enumerator;
		}

		public void Dispose()
		{
			Interop.ReleaseServer(m_enumerator);
			m_enumerator = null;
		}

		public string[] Next(int count)
		{
			try
			{
				nint pArray = Marshal.AllocCoTaskMem(Marshal.SizeOf(typeof(nint)) * count);
				try
				{
					int pceltFetched = 0;
					m_enumerator.RemoteNext(count, pArray, out pceltFetched);
					if (pceltFetched == 0)
					{
						return new string[0];
					}
					return Interop.GetUnicodeStrings(ref pArray, pceltFetched, deallocate: true);
				}
				finally
				{
					Marshal.FreeCoTaskMem(pArray);
				}
			}
			catch (Exception)
			{
				return null;
			}
		}

		public void Skip(int count)
		{
			m_enumerator.Skip(count);
		}

		public void Reset()
		{
			m_enumerator.Reset();
		}

		public EnumString Clone()
		{
			OpcDaComRcw.Comn.IEnumString ppenum = null;
			m_enumerator.Clone(out ppenum);
			return new EnumString(ppenum);
		}
	}
	[Serializable]
	public class Factory : OpcDaNetApi.Factory
	{
		public Factory()
			: base(null, useRemoting: false)
		{
		}

		public Factory(bool useRemoting)
			: base(null, useRemoting)
		{
		}

		protected Factory(SerializationInfo info, StreamingContext context)
			: base(info, context)
		{
		}

		public override OpcDaNetApi.IServer CreateInstance(URL url, ConnectData connectData)
		{
			object obj = Connect(url, connectData);
			if (obj == null)
			{
				return null;
			}
			Server server = null;
			System.Type type = null;
			try
			{
				if (url.Scheme == "opcda")
				{
					if (!typeof(IOPCServer).IsInstanceOfType(obj))
					{
						type = typeof(IOPCServer);
						throw new NotSupportedException();
					}
					if (typeof(IOPCBrowse).IsInstanceOfType(obj) && typeof(IOPCItemIO).IsInstanceOfType(obj))
					{
						server = new OpcDaNetApiCom.Da.Server(url, obj);
					}
					else
					{
						if (!typeof(IOPCItemProperties).IsInstanceOfType(obj))
						{
							type = typeof(IOPCItemProperties);
							throw new NotSupportedException();
						}
						server = new OpcDaNetApiCom.Da20.Server(url, obj);
					}
				}
				else if (url.Scheme == "opcae")
				{
