		public void OnCancelComplete(int dwCancelID)
		{
			try
			{
				lock (this)
				{
					Request request = (Request)m_requests[dwCancelID];
					if (request != null)
					{
						request.OnCancelComplete();
						m_requests.Remove(request.RequestID);
