	public class Interop
	{
		internal static OPCHDA_FILETIME Convert(System.Runtime.InteropServices.ComTypes.FILETIME input)
		{
			return new OPCHDA_FILETIME
			{
				dwLowDateTime = input.dwLowDateTime,
				dwHighDateTime = input.dwHighDateTime
			};
		}

		internal static System.Runtime.InteropServices.ComTypes.FILETIME Convert(OPCHDA_FILETIME input)
		{
			return new System.Runtime.InteropServices.ComTypes.FILETIME
			{
				dwLowDateTime = input.dwLowDateTime,
				dwHighDateTime = input.dwHighDateTime
			};
		}

		internal static OPCHDA_FILETIME GetFILETIME(decimal input)
		{
			return new OPCHDA_FILETIME
			{
				dwHighDateTime = (int)(((ulong)(input * 10000000m) & 0xFFFFFFFF00000000uL) >> 32),
				dwLowDateTime = (int)((ulong)(input * 10000000m) & 0xFFFFFFFFu)
			};
		}

		internal static OPCHDA_FILETIME[] GetFILETIMEs(DateTime[] input)
		{
			OPCHDA_FILETIME[] array = null;
			if (input != null)
			{
				array = new OPCHDA_FILETIME[input.Length];
				for (int i = 0; i < input.Length; i++)
				{
					ref OPCHDA_FILETIME reference = ref array[i];
					reference = Convert(OpcDaNetApiCom.Interop.GetFILETIME(input[i]));
				}
			}
			return array;
		}

		internal static OPCHDA_TIME GetTime(Time input)
		{
			OPCHDA_TIME result = default(OPCHDA_TIME);
			if (input != null)
			{
				result.ftTime = Convert(OpcDaNetApiCom.Interop.GetFILETIME(input.AbsoluteTime));
				result.szTime = (input.IsRelative ? input.ToString() : "");
				result.bString = (input.IsRelative ? 1 : 0);
			}
			else
			{
				result.ftTime = Convert(OpcDaNetApiCom.Interop.GetFILETIME(DateTime.MinValue));
				result.szTime = "";
				result.bString = 1;
			}
