			m_requestID = requestID;
		}

		public bool Update(int cancelID, OpcDaNetApi.ItemIdentifier[] results)
		{
			lock (this)
			{
				m_cancelID = cancelID;
				m_items = new Hashtable();
				foreach (OpcDaNetApi.ItemIdentifier itemIdentifier in results)
				{
					if (!typeof(IResult).IsInstanceOfType(itemIdentifier) || ((IResult)itemIdentifier).ResultID.Succeeded())
					{
						m_items[itemIdentifier.ServerHandle] = new OpcDaNetApi.ItemIdentifier(itemIdentifier);
					}
				}
				if (m_items.Count == 0)
				{
					return true;
				}
				bool result = false;
				if (m_results != null)
				{
					foreach (object result2 in m_results)
					{
						result = InvokeCallback(result2);
					}
				}
				return result;
			}
		}

