		private void Advise()
		{
			if (m_connection == null)
			{
				try
				{
					m_connection = new ConnectionPoint(m_server, typeof(IOPCHDA_DataCallback).GUID);
					m_connection.Advise(m_callback);
				}
				catch
				{
					m_connection = null;
				}
			}
		}

		private void Unadvise()
		{
			if (m_connection != null && m_connection.Unadvise() == 0)
			{
				m_connection.Dispose();
				m_connection = null;
			}
		}

		private int CreateHandle()
		{
			return NextHandle++;
		}

		private int GetInvalidHandle()
		{
			int num = 0;
			foreach (OpcDaNetApi.ItemIdentifier value in m_items.Values)
			{
				int num2 = (int)value.ServerHandle;
				if (num < num2)
				{
					num = num2;
				}
			}
			return num + 1;
		}

		private int GetCount(ICollection[] collections)
		{
			int num = 0;
			if (collections != null)
			{
				foreach (ICollection collection in collections)
				{
					if (collection != null)
					{
						num += collection.Count;
					}
				}
			}
			return num;
		}

		private ResultCollection[] CreateResultCollections(OpcDaNetApi.ItemIdentifier[] items)
		{
			ResultCollection[] array = null;
			if (items != null)
			{
				array = new ResultCollection[items.Length];
				for (int i = 0; i < items.Length; i++)
				{
					array[i] = new ResultCollection();
					if (items[i] != null)
					{
						UpdateResult(items[i], array[i], 0);
					}
				}
			}
			return array;
		}

		private int[] GetServerHandles(OpcDaNetApi.ItemIdentifier[] items)
		{
			int invalidHandle = GetInvalidHandle();
			int[] array = new int[items.Length];
			for (int i = 0; i < items.Length; i++)
			{
				array[i] = invalidHandle;
				if (items[i] != null && items[i].ServerHandle != null)
				{
					OpcDaNetApi.ItemIdentifier itemIdentifier = (OpcDaNetApi.ItemIdentifier)m_items[items[i].ServerHandle];
					if (itemIdentifier != null)
					{
						array[i] = (int)itemIdentifier.ServerHandle;
					}
				}
			}
			return array;
		}

		private int[] GetAggregateIDs(OpcDaNetApi.Hda.Item[] items)
		{
			int[] array = new int[items.Length];
			for (int i = 0; i < items.Length; i++)
			{
				array[i] = 0;
				if (items[i].AggregateID != 0)
				{
					array[i] = items[i].AggregateID;
				}
			}
			return array;
		}

		private void UpdateResult(OpcDaNetApi.ItemIdentifier item, OpcDaNetApi.ItemIdentifier result, int error)
		{
			result.ItemName = item.ItemName;
			result.ItemPath = item.ItemPath;
			result.ClientHandle = item.ClientHandle;
			result.ServerHandle = item.ServerHandle;
			if (error >= 0 && item.ServerHandle != null)
			{
				OpcDaNetApi.ItemIdentifier itemIdentifier = (OpcDaNetApi.ItemIdentifier)m_items[item.ServerHandle];
				if (itemIdentifier != null)
				{
					result.ItemName = itemIdentifier.ItemName;
					result.ItemPath = itemIdentifier.ItemPath;
					result.ClientHandle = itemIdentifier.ClientHandle;
				}
			}
		}

		private void UpdateActualTimes(IActualTime[] results, OPCHDA_TIME pStartTime, OPCHDA_TIME pEndTime)
		{
			DateTime fILETIME = OpcDaNetApiCom.Interop.GetFILETIME(Interop.Convert(pStartTime.ftTime));
			DateTime fILETIME2 = OpcDaNetApiCom.Interop.GetFILETIME(Interop.Convert(pEndTime.ftTime));
			foreach (IActualTime obj in results)
			{
				obj.StartTime = fILETIME;
				obj.EndTime = fILETIME2;
			}
		}

		private ItemAttributeCollection UpdateResults(OpcDaNetApi.ItemIdentifier item, AttributeValueCollection[] attributes, ref nint pErrors)
		{
			int[] int32s = OpcDaNetApiCom.Interop.GetInt32s(ref pErrors, attributes.Length, deallocate: true);
			if (attributes == null || int32s == null)
			{
				throw new InvalidResponseException();
			}
			for (int i = 0; i < attributes.Length; i++)
			{
				attributes[i].ResultID = OpcDaNetApiCom.Interop.GetResultID(int32s[i]);
			}
			ItemAttributeCollection itemAttributeCollection = new ItemAttributeCollection();
			foreach (AttributeValueCollection value in attributes)
			{
				itemAttributeCollection.Add(value);
			}
			UpdateResult(item, itemAttributeCollection, 0);
			return itemAttributeCollection;
		}

		private void UpdateResults(OpcDaNetApi.ItemIdentifier[] items, OpcDaNetApi.ItemIdentifier[] results, ref nint pErrors)
		{
			int[] int32s = OpcDaNetApiCom.Interop.GetInt32s(ref pErrors, items.Length, deallocate: true);
			if (results == null || int32s == null)
			{
				throw new InvalidResponseException();
			}
			for (int i = 0; i < results.Length; i++)
			{
				UpdateResult(items[i], results[i], int32s[i]);
				if (typeof(IResult).IsInstanceOfType(results[i]))
				{
					((IResult)results[i]).ResultID = OpcDaNetApiCom.Interop.GetResultID(int32s[i]);
				}
			}
		}

		private void UpdateResults(ICollection[] items, ResultCollection[] results, int count, ref nint pErrors)
		{
			int[] int32s = OpcDaNetApiCom.Interop.GetInt32s(ref pErrors, count, deallocate: true);
			if (int32s == null)
			{
				throw new InvalidResponseException();
			}
			int num = 0;
			for (int i = 0; i < items.Length; i++)
			{
				for (int j = 0; j < items[i].Count; j++)
				{
					if (num >= count)
					{
						break;
					}
					Result value = new Result(OpcDaNetApiCom.Interop.GetResultID(int32s[num++]));
					results[i].Add(value);
				}
			}
		}

		private int MarshalValues(ItemValueCollection[] items, ref int[] handles, ref object[] values, ref int[] qualities, ref DateTime[] timestamps)
		{
			int count = GetCount(items);
			handles = new int[count];
			timestamps = new DateTime[count];
			values = new object[count];
			qualities = new int[count];
			int[] serverHandles = GetServerHandles(items);
			int num = 0;
			for (int i = 0; i < items.Length; i++)
			{
				foreach (OpcDaNetApi.Hda.ItemValue item in items[i])
				{
					handles[num] = serverHandles[i];
					ref DateTime reference = ref timestamps[num];
					reference = item.Timestamp;
					values[num] = OpcDaNetApiCom.Interop.GetVARIANT(item.Value);
					qualities[num] = item.Quality.GetCode();
					num++;
				}
			}
			return count;
		}

		private int MarshalTimestamps(ItemTimeCollection[] items, ref int[] handles, ref DateTime[] timestamps)
		{
			int count = GetCount(items);
			handles = new int[count];
			timestamps = new DateTime[count];
			int[] serverHandles = GetServerHandles(items);
			int num = 0;
			for (int i = 0; i < items.Length; i++)
			{
				foreach (DateTime item in items[i])
				{
					handles[num] = serverHandles[i];
					timestamps[num] = item;
					num++;
				}
			}
			return count;
		}

		private int MarshalAnnotatations(AnnotationValueCollection[] items, ref int[] serverHandles, ref OPCHDA_FILETIME[] ftTimestamps, ref OPCHDA_ANNOTATION[] annotations)
		{
			int count = GetCount(items);
			int[] serverHandles2 = GetServerHandles(items);
			serverHandles = new int[count];
			annotations = new OPCHDA_ANNOTATION[count];
			DateTime[] array = new DateTime[count];
			int num = 0;
			for (int i = 0; i < items.Length; i++)
			{
				for (int j = 0; j < items[i].Count; j++)
				{
					serverHandles[num] = serverHandles2[i];
					ref DateTime reference = ref array[num];
					reference = items[i][j].Timestamp;
					annotations[num] = default(OPCHDA_ANNOTATION);
					annotations[num].dwNumValues = 1;
					annotations[num].ftTimeStamps = OpcDaNetApiCom.Interop.GetFILETIMEs(new DateTime[1] { array[j] });
					annotations[num].szAnnotation = OpcDaNetApiCom.Interop.GetUnicodeStrings(new string[1] { items[i][j].Annotation });
					annotations[num].ftAnnotationTime = OpcDaNetApiCom.Interop.GetFILETIMEs(new DateTime[1] { items[i][j].CreationTime });
					annotations[num].szUser = OpcDaNetApiCom.Interop.GetUnicodeStrings(new string[1] { items[i][j].User });
					num++;
				}
			}
			ftTimestamps = Interop.GetFILETIMEs(array);
			return count;
		}

		private OpcDaNetApi.IdentifiedResult[] GetIdentifiedResults(ResultCollection[] results)
		{
			if (results == null || results.Length == 0)
			{
				return new OpcDaNetApi.IdentifiedResult[0];
			}
			OpcDaNetApi.IdentifiedResult[] array = new OpcDaNetApi.IdentifiedResult[results.Length];
			for (int i = 0; i < results.Length; i++)
			{
				array[i] = new OpcDaNetApi.IdentifiedResult(results[i]);
				if (results[i] == null || results[i].Count == 0)
				{
					array[i].ResultID = ResultID.Hda.S_NODATA;
					continue;
				}
				ResultID resultID = results[i][0].ResultID;
				foreach (Result item in results[i])
				{
					if (resultID.Code != item.ResultID.Code)
					{
						resultID = ResultID.E_FAIL;
						break;
					}
				}
			}
			return array;
		}
	}
