		private void CleanupContinuationPoints()
		{
			ArrayList arrayList = new ArrayList();
			foreach (DictionaryEntry continuationPoint2 in m_continuationPoints)
			{
				try
				{
					ContinuationPoint continuationPoint = continuationPoint2.Value as ContinuationPoint;
					if (DateTime.UtcNow.Ticks - continuationPoint.Timestamp.Ticks > 6000000000L)
					{
						arrayList.Add(continuationPoint2.Key);
					}
				}
				catch
				{
					arrayList.Add(continuationPoint2.Key);
				}
			}
			foreach (string item in arrayList)
			{
				ContinuationPoint obj2 = (ContinuationPoint)m_continuationPoints[item];
				m_continuationPoints.Remove(item);
				obj2.Position.Dispose();
			}
		}

		private bool IsItem(string name)
		{
			OpcDaNetApi.ItemIdentifier itemIdentifier = new OpcDaNetApi.ItemIdentifier(name);
			try
			{
				ItemPropertyCollection[] properties = m_server.GetProperties(new OpcDaNetApi.ItemIdentifier[1] { itemIdentifier }, new PropertyID[1] { Property.DATATYPE }, returnValues: false);
				if (properties == null || properties.Length != 1)
				{
					return false;
				}
				if (properties[0].ResultID.Failed() || properties[0][0].ResultID.Failed())
				{
					return false;
				}
				return true;
			}
			catch (Exception)
			{
				return false;
			}
		}

		private OpcDaNetApi.Da.BrowseElement FindChild(string name)
		{
			OpcDaNetApi.ItemIdentifier itemID = null;
			if (m_browseStack.Count > 0)
			{
				itemID = (OpcDaNetApi.ItemIdentifier)m_browseStack.Peek();
			}
			OpcDaNetApi.Da.BrowseElement[] array = null;
			try
			{
				BrowseFilters browseFilters = new BrowseFilters();
				browseFilters.MaxElementsReturned = 0;
				browseFilters.BrowseFilter = browseFilter.all;
				browseFilters.ElementNameFilter = name;
				browseFilters.VendorFilter = null;
				browseFilters.ReturnAllProperties = false;
				browseFilters.PropertyIDs = null;
				browseFilters.ReturnPropertyValues = false;
				OpcDaNetApi.Da.BrowsePosition position = null;
				array = m_server.Browse(itemID, browseFilters, out position);
				if (position != null)
				{
					position.Dispose();
					position = null;
				}
			}
			catch (Exception)
			{
				return null;
			}
			if (array != null && array.Length != 0)
			{
				return array[0];
			}
			return null;
		}

		private void BuildBrowseStack(OpcDaNetApi.ItemIdentifier itemID)
		{
			m_browseStack.Clear();
			BuildBrowseStack(null, itemID);
		}

		private bool BuildBrowseStack(OpcDaNetApi.ItemIdentifier itemID, OpcDaNetApi.ItemIdentifier targetID)
		{
			BrowseFilters browseFilters = new BrowseFilters();
			browseFilters.MaxElementsReturned = 0;
			browseFilters.BrowseFilter = browseFilter.all;
			browseFilters.ElementNameFilter = null;
			browseFilters.VendorFilter = null;
			browseFilters.ReturnAllProperties = false;
			browseFilters.PropertyIDs = null;
			browseFilters.ReturnPropertyValues = false;
			OpcDaNetApi.Da.BrowseElement[] array = null;
			OpcDaNetApi.Da.BrowsePosition position = null;
			try
			{
				array = m_server.Browse(itemID, browseFilters, out position);
			}
			catch (Exception)
			{
				m_browseStack.Clear();
				return false;
			}
			if (position != null)
			{
				position.Dispose();
				position = null;
			}
			if (array == null || array.Length == 0)
			{
				m_browseStack.Clear();
				return false;
			}
			OpcDaNetApi.Da.BrowseElement[] array2 = array;
			foreach (OpcDaNetApi.Da.BrowseElement browseElement in array2)
			{
				if (browseElement.ItemName == targetID.ItemName)
				{
					return true;
				}
				if (targetID.ItemName.StartsWith(browseElement.ItemName))
				{
					OpcDaNetApi.ItemIdentifier itemIdentifier = new OpcDaNetApi.ItemIdentifier(targetID.ItemName);
					m_browseStack.Push(itemIdentifier);
					return BuildBrowseStack(itemIdentifier, targetID);
				}
			}
			return false;
		}

		private void Browse(OpcDaNetApi.ItemIdentifier itemID, OPCBROWSETYPE dwBrowseFilterType, string szFilterCriteria, short vtDataTypeFilter, int dwAccessRightsFilter, ArrayList hits)
		{
			BrowseFilters browseFilters = new BrowseFilters();
			browseFilters.MaxElementsReturned = 0;
			browseFilters.BrowseFilter = browseFilter.all;
			browseFilters.ElementNameFilter = ((dwBrowseFilterType != OPCBROWSETYPE.OPC_FLAT) ? szFilterCriteria : "");
			browseFilters.VendorFilter = null;
			browseFilters.ReturnAllProperties = false;
			browseFilters.PropertyIDs = new PropertyID[2]
			{
				Property.DATATYPE,
				Property.ACCESSRIGHTS
			};
			browseFilters.ReturnPropertyValues = true;
			OpcDaNetApi.Da.BrowseElement[] array = null;
			try
			{
				OpcDaNetApi.Da.BrowsePosition position = null;
				array = m_server.Browse(itemID, browseFilters, out position);
				if (position != null)
				{
					position.Dispose();
					position = null;
				}
			}
			catch
			{
				throw new ExternalException("BrowseOPCItemIDs", -2147467259);
			}
			OpcDaNetApi.Da.BrowseElement[] array2 = array;
			foreach (OpcDaNetApi.Da.BrowseElement browseElement in array2)
			{
				switch (dwBrowseFilterType)
				{
				case OPCBROWSETYPE.OPC_FLAT:
					if (browseElement.HasChildren)
					{
						Browse(new OpcDaNetApi.ItemIdentifier(browseElement.ItemName), dwBrowseFilterType, szFilterCriteria, vtDataTypeFilter, dwAccessRightsFilter, hits);
					}
					break;
				case OPCBROWSETYPE.OPC_BRANCH:
					if (!browseElement.HasChildren)
					{
						continue;
					}
					break;
				case OPCBROWSETYPE.OPC_LEAF:
					if (browseElement.HasChildren)
					{
						continue;
					}
					break;
				}
				if (browseElement.IsItem)
				{
					if (vtDataTypeFilter != 0 && (short)OpcDaNetApiCom.Interop.GetType((System.Type)browseElement.Properties[0].Value) != vtDataTypeFilter)
					{
						continue;
					}
					if (dwAccessRightsFilter != 0)
					{
						accessRights accessRights2 = (accessRights)browseElement.Properties[1].Value;
						if ((dwAccessRightsFilter == 1 && accessRights2 == accessRights.writable) || (dwAccessRightsFilter == 2 && accessRights2 == accessRights.readable))
						{
							continue;
						}
					}
				}
				if (dwBrowseFilterType != OPCBROWSETYPE.OPC_FLAT)
				{
					hits.Add(browseElement.Name);
				}
