	public class ServerEnumerator : IDisposable
	{
		private IOPCServerList2 m_server;

		private string m_host;

		private static readonly Guid OPCEnumCLSID = new Guid("13486D51-4821-11D2-A494-3CB306C10000");

		public ServerEnumerator()
		{
			Initialize();
		}

		private void Initialize()
		{
			m_server = null;
			m_host = null;
		}

		~ServerEnumerator()
		{
			Dispose(disposing: false);
		}

		public void Dispose()
		{
			Dispose(disposing: true);
			GC.SuppressFinalize(this);
		}

		protected virtual void Dispose(bool disposing)
		{
			if (m_server != null)
			{
				Utils.ReleaseServer(m_server);
				m_server = null;
			}
		}

		public void Connect()
		{
			Connect(null, null, null, null);
		}

		public void Connect(string host, string username, string password, string domain)
		{
			Disconnect();
			object obj = null;
			try
			{
				obj = Utils.CreateInstance(OPCEnumCLSID, host, username, password, domain);
			}
			catch (Exception e)
			{
				throw Utils.CreateComException(e);
			}
			m_server = obj as IOPCServerList2;
			if (m_server == null)
			{
				Utils.ReleaseServer(obj);
				StringBuilder stringBuilder = new StringBuilder();
				stringBuilder.Append("Server does not support IOPCServerList2. ");
				stringBuilder.Append("The OPC proxy/stubs may not be installed properly or the client or server machine. ");
				stringBuilder.Append("The also could be a problem with DCOM security configuration.");
				throw Utils.CreateComException(-2147467262, stringBuilder.ToString());
			}
			m_host = host;
			if (string.IsNullOrEmpty(m_host))
			{
				m_host = "localhost";
			}
		}

		public void Disconnect()
		{
			try
			{
				if (m_server != null)
				{
					Utils.ReleaseServer(m_server);
					m_server = null;
				}
			}
			catch (Exception e)
			{
				throw Utils.CreateComException(e, -2147467259, "Could not release OPCEnum server.");
			}
		}

		public ServerDescription[] GetAvailableServers(params Guid[] catids)
		{
			try
			{
				IOPCEnumGUID ppenumClsid = null;
				m_server.EnumClassesOfCategories(catids.Length, catids, 0, null, out ppenumClsid);
				List<Guid> list = ReadClasses(ppenumClsid);
				Utils.ReleaseServer(ppenumClsid);
				ppenumClsid = null;
				ServerDescription[] array = new ServerDescription[list.Count];
				for (int i = 0; i < array.Length; i++)
				{
					array[i] = ReadServerDetails(list[i]);
				}
				return array;
			}
			catch (Exception e)
			{
				throw Utils.CreateComException(e, -2147467259, "Could not enumerate COM servers.");
			}
		}

		public Guid CLSIDFromProgID(string progID)
		{
			Guid clsid;
			try
			{
				m_server.CLSIDFromProgID(progID, out clsid);
			}
			catch
			{
				return Guid.Empty;
			}
			return clsid;
		}

		private List<Guid> ReadClasses(IOPCEnumGUID enumerator)
		{
			List<Guid> list = new List<Guid>();
			int pceltFetched = 0;
			Guid[] array = new Guid[10];
			do
			{
				try
				{
					nint num = Marshal.AllocCoTaskMem(Marshal.SizeOf(typeof(Guid)) * array.Length);
					try
					{
						enumerator.Next(array.Length, num, out pceltFetched);
						if (pceltFetched > 0)
						{
							nint ptr = num;
							for (int i = 0; i < pceltFetched; i++)
							{
								array[i] = (Guid)Marshal.PtrToStructure(ptr, typeof(Guid));
								ptr = (nint)(((IntPtr)ptr).ToInt64() + Marshal.SizeOf(typeof(Guid)));
								list.Add(array[i]);
							}
						}
					}
					finally
					{
						Marshal.FreeCoTaskMem(num);
					}
				}
				catch
				{
					break;
				}
			}
			while (pceltFetched > 0);
			return list;
		}

		private ServerDescription ReadServerDetails(Guid clsid)
		{
			ServerDescription serverDescription = new ServerDescription();
			serverDescription.HostName = m_host;
			serverDescription.Clsid = clsid;
			string ppszProgID = null;
			try
			{
				string ppszUserType = null;
				string ppszVerIndProgID = null;
				m_server.GetClassDetails(ref clsid, out ppszProgID, out ppszUserType, out ppszVerIndProgID);
				if (!string.IsNullOrEmpty(ppszVerIndProgID))
				{
					ppszProgID = ppszVerIndProgID;
				}
				serverDescription.Description = ppszUserType;
				serverDescription.VersionIndependentProgId = ppszVerIndProgID;
			}
			catch
			{
				ppszProgID = null;
			}
			serverDescription.ProgId = ppszProgID;
			return serverDescription;
		}
	}
	public static class Utils
	{
		private class ServerInfo
		{
			private GCHandle m_hUserName;

			private GCHandle m_hPassword;

			private GCHandle m_hDomain;

			private GCHandle m_hIdentity;

			private GCHandle m_hAuthInfo;

			public COSERVERINFO Allocate(string hostName, string username, string password, string domain)
			{
				COSERVERINFO result = new COSERVERINFO
				{
					pwszName = hostName,
					pAuthInfo = IntPtr.Zero,
					dwReserved1 = 0u,
					dwReserved2 = 0u
				};
				if (string.IsNullOrEmpty(username))
				{
					return result;
				}
				m_hUserName = GCHandle.Alloc(username, GCHandleType.Pinned);
				m_hPassword = GCHandle.Alloc(password, GCHandleType.Pinned);
				m_hDomain = GCHandle.Alloc(domain, GCHandleType.Pinned);
				m_hIdentity = default(GCHandle);
				m_hIdentity = GCHandle.Alloc(new COAUTHIDENTITY
				{
					User = m_hUserName.AddrOfPinnedObject(),
					UserLength = (uint)(username?.Length ?? 0),
					Password = m_hPassword.AddrOfPinnedObject(),
					PasswordLength = (uint)(password?.Length ?? 0),
					Domain = m_hDomain.AddrOfPinnedObject(),
					DomainLength = (uint)(domain?.Length ?? 0),
					Flags = 2u
				}, GCHandleType.Pinned);
				m_hAuthInfo = GCHandle.Alloc(new COAUTHINFO
				{
					dwAuthnSvc = 10u,
					dwAuthzSvc = 0u,
					pwszServerPrincName = IntPtr.Zero,
					dwAuthnLevel = 2u,
					dwImpersonationLevel = 3u,
					pAuthIdentityData = m_hIdentity.AddrOfPinnedObject(),
					dwCapabilities = 0u
				}, GCHandleType.Pinned);
				result.pAuthInfo = m_hAuthInfo.AddrOfPinnedObject();
				return result;
			}

			public void Deallocate()
			{
				if (m_hUserName.IsAllocated)
				{
					m_hUserName.Free();
				}
				if (m_hPassword.IsAllocated)
				{
					m_hPassword.Free();
				}
				if (m_hDomain.IsAllocated)
				{
					m_hDomain.Free();
				}
				if (m_hIdentity.IsAllocated)
				{
					m_hIdentity.Free();
				}
				if (m_hAuthInfo.IsAllocated)
				{
					m_hAuthInfo.Free();
				}
			}
		}

