		private static void VerifyCodebase(Assembly assembly, string filepath)
		{
			string text = assembly.CodeBase.ToLower();
			string text2 = filepath.Replace('\\', '/').Replace("//", "/").ToLower();
			if (!text2.StartsWith("file:///"))
			{
				text2 = "file:///" + text2;
			}
			if (text != text2)
			{
				throw new ApplicationException($"Duplicate assembly loaded. You need to restart the application.\r\n{text}\r\n{text2}");
			}
		}

		public static string GetSystemMessage(int error, int localeId)
		{
			int dwLanguageId = localeId switch
			{
				2048 => GetSystemDefaultLangID(), 
				1024 => GetUserDefaultLangID(), 
				_ => 0xFFFF & localeId, 
			};
			nint num = Marshal.AllocCoTaskMem(1024);
			if (FormatMessageW(4096, IntPtr.Zero, error, dwLanguageId, num, 1023, IntPtr.Zero) > 0)
			{
				string text = Marshal.PtrToStringUni(num);
				Marshal.FreeCoTaskMem(num);
				if (text != null && text.Length > 0)
				{
					return text.Trim();
				}
			}
			return $"0x{error:X8}";
		}

		public static string ProgIDFromCLSID(Guid clsid)
		{
			RegistryKey registryKey = Registry.ClassesRoot.OpenSubKey($"CLSID\\{{{clsid}}}\\ProgId");
			if (registryKey != null)
