		public static List<Guid> EnumClassesInCategories(params Guid[] categories)
		{
			ICatInformation catInformation = (ICatInformation)CreateLocalServer(CLSID_StdComponentCategoriesMgr);
			object ppenumClsid = null;
			try
			{
				catInformation.EnumClassesOfCategories(1, categories, 0, null, out ppenumClsid);
				IEnumGUID enumGUID = (IEnumGUID)ppenumClsid;
				List<Guid> list = new List<Guid>();
				Guid[] array = new Guid[10];
				while (true)
				{
					int pceltFetched = 0;
					nint num = Marshal.AllocCoTaskMem(Marshal.SizeOf(typeof(Guid)) * array.Length);
					try
					{
						enumGUID.Next(array.Length, num, out pceltFetched);
						if (pceltFetched == 0)
						{
							break;
						}
						nint ptr = num;
						for (int i = 0; i < pceltFetched; i++)
						{
							array[i] = (Guid)Marshal.PtrToStructure(ptr, typeof(Guid));
							ptr = (nint)(((IntPtr)ptr).ToInt64() + Marshal.SizeOf(typeof(Guid)));
						}
						goto IL_00c0;
					}
					finally
					{
						Marshal.FreeCoTaskMem(num);
					}
					IL_00c0:
					for (int j = 0; j < pceltFetched; j++)
					{
						list.Add(array[j]);
					}
				}
				return list;
			}
			finally
			{
				ReleaseServer(ppenumClsid);
				ReleaseServer(catInformation);
			}
		}

