			if (registryKey != null)
			{
				try
				{
					if (!(registryKey.GetValue("Codebase") is string result))
					{
						return registryKey.GetValue(null) as string;
					}
					return result;
				}
				finally
				{
					registryKey.Close();
				}
			}
			return null;
		}

		public static object CreateLocalServer(Guid clsid)
		{
			COSERVERINFO pServerInfo = new COSERVERINFO
			{
				pwszName = null,
				pAuthInfo = IntPtr.Zero,
				dwReserved1 = 0u,
				dwReserved2 = 0u
			};
			GCHandle gCHandle = GCHandle.Alloc(IID_IUnknown, GCHandleType.Pinned);
			MULTI_QI[] array = new MULTI_QI[1];
			array[0].iid = gCHandle.AddrOfPinnedObject();
			array[0].pItf = null;
			array[0].hr = 0u;
			try
			{
				CoCreateInstanceEx(ref clsid, null, 5u, ref pServerInfo, 1u, array);
			}
			finally
			{
				gCHandle.Free();
			}
			if (array[0].hr != 0)
			{
				throw new ExternalException("CoCreateInstanceEx: 0x{0:X8}" + array[0].hr);
			}
			return array[0].pItf;
		}

		public static object CreateInstance(Guid clsid, string hostName, string username, string password, string domain)
		{
			ServerInfo serverInfo = new ServerInfo();
			COSERVERINFO pServerInfo = serverInfo.Allocate(hostName, username, password, domain);
			GCHandle gCHandle = GCHandle.Alloc(IID_IUnknown, GCHandleType.Pinned);
			MULTI_QI[] array = new MULTI_QI[1];
			array[0].iid = gCHandle.AddrOfPinnedObject();
			array[0].pItf = null;
			array[0].hr = 0u;
			try
			{
				uint dwClsCtx = 5u;
				if (!string.IsNullOrEmpty(hostName) && hostName != "localhost")
				{
					dwClsCtx = 20u;
				}
				CoCreateInstanceEx(ref clsid, null, dwClsCtx, ref pServerInfo, 1u, array);
			}
			finally
			{
				if (gCHandle.IsAllocated)
				{
					gCHandle.Free();
				}
				serverInfo.Deallocate();
			}
			if (array[0].hr != 0)
			{
				throw CreateComException(-2147467259, "Could not create COM server '{0}' on host '{1}'. Reason: {2}.", clsid, hostName, GetSystemMessage((int)array[0].hr, 2048));
			}
			return array[0].pItf;
		}

		public static void ReleaseServer(object server)
		{
			if (server != null && server.GetType().IsCOMObject)
			{
