		}

		public static void RegisterClassInCategory(Guid clsid, Guid catid)
		{
			RegisterClassInCategory(clsid, catid, null);
		}

		public static void RegisterClassInCategory(Guid clsid, Guid catid, string description)
		{
			ICatRegister catRegister = (ICatRegister)CreateLocalServer(CLSID_StdComponentCategoriesMgr);
			try
			{
				string pszDesc = null;
				try
				{
					((ICatInformation)catRegister).GetCategoryDesc(catid, 0, out pszDesc);
				}
				catch (Exception innerException)
				{
					pszDesc = description;
					if (string.IsNullOrEmpty(pszDesc))
					{
						if (catid == CATID_OPCDAServer20)
						{
							pszDesc = "OPC Data Access Servers Version 2.0";
						}
						else if (catid == CATID_OPCDAServer30)
						{
							pszDesc = "OPC Data Access Servers Version 3.0";
						}
						else if (catid == CATID_OPCAEServer10)
						{
							pszDesc = "OPC Alarm & Event Server Version 1.0";
						}
						else
						{
							if (!(catid == CATID_OPCHDAServer10))
							{
								throw new ApplicationException("No description for category available", innerException);
							}
							pszDesc = "OPC History Data Access Servers Version 1.0";
						}
					}
					CATEGORYINFO cATEGORYINFO = default(CATEGORYINFO);
					cATEGORYINFO.catid = catid;
					cATEGORYINFO.lcid = 0;
					cATEGORYINFO.szDescription = pszDesc;
					catRegister.RegisterCategories(1, new CATEGORYINFO[1] { cATEGORYINFO });
				}
				catRegister.RegisterClassImplCategories(clsid, 1, new Guid[1] { catid });
			}
			finally
			{
				ReleaseServer(catRegister);
			}
		}

		public static void UnregisterComServer(Guid clsid)
		{
			string name = $"CLSID\\{{{clsid}}}\\Implemented Categories";
			RegistryKey registryKey = Registry.ClassesRoot.OpenSubKey(name);
			if (registryKey != null)
			{
				try
				{
					string[] subKeyNames = registryKey.GetSubKeyNames();
					foreach (string text in subKeyNames)
					{
						try
						{
							UnregisterClassInCategory(clsid, new Guid(text.Substring(1, text.Length - 2)));
						}
						catch (Exception)
						{
						}
					}
				}
				finally
				{
					registryKey.Close();
				}
			}
			string name2 = $"CLSID\\{{{clsid}}}\\ProgId";
			registryKey = Registry.ClassesRoot.OpenSubKey(name2);
			if (registryKey != null)
			{
				string text2 = registryKey.GetValue(null) as string;
				registryKey.Close();
				if (!string.IsNullOrEmpty(text2))
				{
					try
					{
						Registry.ClassesRoot.DeleteSubKeyTree(text2);
					}
					catch (Exception)
					{
					}
				}
			}
			try
			{
				Registry.ClassesRoot.DeleteSubKeyTree($"CLSID\\{{{clsid}}}");
			}
			catch (Exception)
			{
			}
		}

		public static void UnregisterClassInCategory(Guid clsid, Guid catid)
		{
			ICatRegister catRegister = (ICatRegister)CreateLocalServer(CLSID_StdComponentCategoriesMgr);
			try
			{
				catRegister.UnRegisterClassImplCategories(clsid, 1, new Guid[1] { catid });
			}
			finally
			{
				ReleaseServer(catRegister);
			}
		}

		public static Exception CreateComException(Exception e)
		{
			return CreateComException(e, 0, null);
		}

		public static Exception CreateComException(int code, string message, params object[] args)
		{
			return CreateComException(null, code, message, args);
		}

		public static Exception CreateComException(Exception e, int code, string message, params object[] args)
		{
			if (code == 0)
			{
				code = ((!(e is COMException)) ? (-2147467259) : ((COMException)e).ErrorCode);
			}
			if (string.IsNullOrEmpty(message))
			{
				message = ((e == null) ? GetSystemMessage(code, CultureInfo.CurrentUICulture.LCID) : e.Message);
			}
			else if (args != null && args.Length != 0)
			{
				message = string.Format(CultureInfo.CurrentUICulture, message, args);
			}
			return new COMException(message, code);
		}

