namespace Snet.Opc.utility
{
	/// <summary>
	/// OPC 辅助工具类，提供地址分组、订阅地址处理等功能，用于 OPC UA/DA 客户端的节点管理。
	/// </summary>
	public class OpcHelper
	{
		/// <summary>
		/// 订阅地址处理：将地址按指定数量分组，返回以唯一标签为键的线程安全字典。
		/// </summary>
		/// <param name="address">地址数据对象，包含待分组的地址列表</param>
		/// <param name="groupMaxNumber">每组最大订阅数量</param>
		/// <returns>分组后的地址字典；若地址为空则返回 null</returns>
		public static ConcurrentDictionary<string, Address>? SubscribeAddressHandle(Address address, int groupMaxNumber)
		{
			List<AddressDetails> list = ((address != null) ? address.AddressArray : null);
			if (list == null || list.Count <= 0)
			{
				return null;
			}
			ConcurrentDictionary<string, Address> concurrentDictionary = new ConcurrentDictionary<string, Address>();
			foreach (KeyValuePair<int, Address> item in SplitList(address, groupMaxNumber))
			{
				string key = $"{item.Key}-{DateTime.Now:yyyyMMddHHmmssffffff}";
				concurrentDictionary.TryAdd(key, item.Value);
			}
			return concurrentDictionary;
		}

		/// <summary>
		/// 将地址列表按指定数量拆分为多个子集合。
		/// </summary>
		/// <param name="list">包含待拆分地址的对象</param>
		/// <param name="num">每组最大元素数量</param>
		/// <returns>以序号为键、子地址集合为值的字典</returns>
		public static Dictionary<int, Address> SplitList(Address list, int num)
		{
			//IL_0012: Unknown result type (might be due to invalid IL or missing references)
			//IL_0017: Unknown result type (might be due to invalid IL or missing references)
			//IL_0023: Expected O, but got Unknown
			//IL_005d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0062: Unknown result type (might be due to invalid IL or missing references)
			//IL_006e: Expected O, but got Unknown
			int count = list.AddressArray.Count;
			Dictionary<int, Address> dictionary = new Dictionary<int, Address>();
			Address val = new Address
			{
				AddressArray = new List<AddressDetails>()
			};
			int num2 = 0;
			for (int i = 0; i < count; i++)
			{
				val.AddressArray.Add(list.AddressArray[i]);
				if ((i + 1) % num == 0 || i + 1 == count)
				{
					dictionary.Add(num2++, val);
					val = new Address
					{
						AddressArray = new List<AddressDetails>()
					};
				}
			}
			return dictionary;
		}
	}
}
