		/// <summary>
		/// 加载用户指定的服务端应用证书（PFX）。
		/// 校验私钥、有效期、密钥大小及 SAN 是否覆盖监听地址，不满足则抛出明确错误；
		/// 校验通过后把证书复制到 SDK 证书存储，返回标准的证书标识供 SDK 加载。
		/// </summary>
		/// <param name="config">应用配置</param>
		/// <param name="cerRoot">证书根目录</param>
		/// <returns>仅包含指定证书的应用证书集合</returns>
		private CertificateIdentifierCollection LoadApplicationCertificate(ApplicationConfiguration config, string cerRoot)
		{
			//IL_02c9: Unknown result type (might be due to invalid IL or missing references)
			//IL_02d3: Expected O, but got Unknown
			//IL_02d3: Unknown result type (might be due to invalid IL or missing references)
			//IL_02d8: Unknown result type (might be due to invalid IL or missing references)
			//IL_02d9: Unknown result type (might be due to invalid IL or missing references)
			//IL_02de: Unknown result type (might be due to invalid IL or missing references)
			//IL_02e9: Unknown result type (might be due to invalid IL or missing references)
			//IL_02f0: Unknown result type (might be due to invalid IL or missing references)
			//IL_02fc: Unknown result type (might be due to invalid IL or missing references)
			//IL_0308: Unknown result type (might be due to invalid IL or missing references)
			//IL_0318: Expected O, but got Unknown
			//IL_0318: Expected O, but got Unknown
			//IL_031a: Expected O, but got Unknown
			if (string.IsNullOrWhiteSpace(base.basics.SecreKey))
			{
				throw new ArgumentException("服务端应用证书密钥（SecreKey）不能为空");
			}
			if (!File.Exists(base.basics.Cer))
			{
				throw new ArgumentException("服务端应用证书文件不存在：" + base.basics.Cer);
			}
			using X509Certificate2 x509Certificate = new X509Certificate2(base.basics.Cer, base.basics.SecreKey, X509KeyStorageFlags.MachineKeySet | X509KeyStorageFlags.Exportable);
			if (!x509Certificate.HasPrivateKey)
			{
				throw new ArgumentException("服务端应用证书不包含私钥，请提供含私钥的 PFX 证书");
			}
			if (DateTime.UtcNow < x509Certificate.NotBefore || DateTime.UtcNow > x509Certificate.NotAfter)
			{
				throw new ArgumentException($"服务端应用证书已过期（有效期至 {x509Certificate.NotAfter:yyyy-MM-dd}）");
			}
			if (X509Utils.GetPublicKeySize(x509Certificate) < config.SecurityConfiguration.MinimumCertificateKeySize)
			{
				throw new ArgumentException("服务端应用证书密钥长度不足");
			}
			IList<string> domainsFromCertificate = X509Utils.GetDomainsFromCertificate(x509Certificate);
			string listenHost = ((base.basics.IpAddress == "0.0.0.0") ? Utils.GetHostName() : base.basics.IpAddress);
			if (!domainsFromCertificate.Any((string d) => string.Equals(d, base.basics.IpAddress, StringComparison.OrdinalIgnoreCase) || string.Equals(d, "localhost", StringComparison.OrdinalIgnoreCase) || string.Equals(d, listenHost, StringComparison.OrdinalIgnoreCase)))
			{
				throw new ArgumentException($"服务端应用证书的 SAN 域名（{string.Join(", ", domainsFromCertificate)}）不包含监听地址 {base.basics.IpAddress}，无法作为服务端证书");
			}
			IReadOnlyList<string> readOnlyList = default(IReadOnlyList<string>);
			if (!X509Utils.CompareApplicationUriWithCertificate(x509Certificate, config.ApplicationUri, ref readOnlyList))
			{
				throw new ArgumentException($"服务端应用证书不包含 OPC UA ApplicationUri（{config.ApplicationUri}），证书中的 uri 扩展：{((readOnlyList.Count > 0) ? string.Join(", ", readOnlyList) : "无")}。请使用 OPC UA 工具生成含此 ApplicationUri 的证书");
			}
			string text = Path.Combine(cerRoot, "certs");
			string text2 = Path.Combine(cerRoot, "private");
			Directory.CreateDirectory(text);
			Directory.CreateDirectory(text2);
			string thumbprint = x509Certificate.Thumbprint;
			File.WriteAllBytes(Path.Combine(text, thumbprint + ".der"), x509Certificate.RawData);
			File.WriteAllBytes(Path.Combine(text2, thumbprint + ".pfx"), x509Certificate.Export(X509ContentType.Pfx, base.basics.SecreKey));
			config.SecurityConfiguration.CertificatePasswordProvider = (ICertificatePasswordProvider)new CertificatePasswordProvider((ReadOnlySpan<char>)base.basics.SecreKey.ToCharArray());
			CertificateIdentifierCollection val = new CertificateIdentifierCollection();
			((List<CertificateIdentifier>)val).Add(new CertificateIdentifier
			{
				StoreType = "Directory",
				StorePath = cerRoot,
				SubjectName = x509Certificate.Subject,
				Thumbprint = x509Certificate.Thumbprint,
				CertificateTypeString = "RsaSha256"
			});
			return val;
		}

		/// <summary>
		/// 配置证书认证所需的用户证书信任存储。
