			//IL_007c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0087: Unknown result type (might be due to invalid IL or missing references)
			//IL_0093: Expected O, but got Unknown
			string text = ((!string.IsNullOrWhiteSpace(base.basics.TrustedUserPath)) ? base.basics.TrustedUserPath : Path.Combine(cerRoot, "trusted"));
			string text2 = Path.Combine(Path.GetDirectoryName(text) ?? cerRoot, "issuer");
			Directory.CreateDirectory(text);
			Directory.CreateDirectory(text2);
			config.SecurityConfiguration.TrustedUserCertificates = new CertificateTrustList
			{
