			};
		}

		/// <summary>
		/// 启动线程
		/// </summary>
		private async Task StatusThreadAsync(CancellationToken token)
		{
			await Task.Run(async delegate
			{
				while (service != null)
				{
					if (DateTime.UtcNow - LastEventTime > TimeSpan.FromMilliseconds(5000.0))
					{
						IList<ISession> sessions = ((StandardServer)service).CurrentInstance.SessionManager.GetSessions();
						for (int i = 0; i < sessions.Count; i++)
						{
							ISession session = sessions[i];
							PrintSessionStatus(session, "心跳包", IsHeartbeatPacket: true);
						}
						LastEventTime = DateTime.UtcNow;
					}
					await Task.Delay(1000, token).ConfigureAwait(continueOnCapturedContext: false);
				}
			}, token);
		}

		/// <summary>
		/// 会话状态
		/// </summary>
		private unsafe void SessionManager_Session(ISession session, SessionEventReason reason)
		{
			LastEventTime = DateTime.UtcNow;
			PrintSessionStatus(session, ((object)(*(SessionEventReason*)(&reason))/*cast due to constrained. prefix*/).ToString());
		}

		/// <summary>
		/// 订阅状态
		/// </summary>
		private void SubscriptionManager_Subscription(ISubscription subscription, bool deleted)
		{
			LastEventTime = DateTime.UtcNow;
			PrintSessionStatus(subscription.Session, deleted ? "取消订阅" : "订阅");
		}

		/// <summary>
		/// 打印会话状态
		/// </summary>
		/// <param name="session">会话对象</param>
		/// <param name="reason">原因</param>
		/// <param name="IsHeartbeatPacket">是不是心跳包</param>
		private void PrintSessionStatus(ISession session, string reason, bool IsHeartbeatPacket = false)
		{
			//IL_00bb: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c5: Expected O, but got Unknown
			if (session != null)
			{
				string arg = ((object)session.Id).ToString();
				string text = string.Format("[ {0} ] ( {1} ) {2}", session.SessionDiagnostics.SessionName, arg, reason.Equals("Created") ? "创建" : (reason.Equals("Activated") ? "激活" : (reason.Equals("Closing") ? "结束" : (reason.Equals("Impersonating") ? "新身份激活" : reason))));
				if (IsHeartbeatPacket)
				{
					text += $":{session.SessionDiagnostics.ClientLastContactTime.ToLocalTime():HH:mm:ss}";
				}
				if (reason.Equals("Closing"))
				{
					((IDisposable)session).Dispose();
				}
				base.OnInfoEventHandler((object)this, new EventInfoResult(true, text));
			}
		}

