		/// <summary>
		/// 获取文件夹内的地址
		/// </summary>
		/// <returns>返回nodeid集合</returns>
		public List<NodeId> GetFolderAddress(List<NodeId> folderNameArray)
		{
			List<NodeId> list = new List<NodeId>();
			foreach (NodeId folderName in folderNameArray)
			{
				if (m_staticNodes.Count > 0)
				{
					foreach (BaseDataVariableState item in m_staticNodes.Where((BaseDataVariableState s) => ((object)((NodeState)s).NodeId).ToString().Contains(((object)folderName).ToString())).ToList())
					{
						list.Add(((NodeState)item).NodeId);
					}
				}
				if (m_dynamicNodes.Count <= 0)
				{
					continue;
				}
				foreach (BaseDataVariableState item2 in m_dynamicNodes.Where((BaseDataVariableState s) => ((object)((NodeState)s).NodeId).ToString().Contains(((object)folderName).ToString())).ToList())
				{
					list.Add(((NodeState)item2).NodeId);
				}
			}
			return list;
		}

		/// <summary>
