			foreach (BaseDataVariableState staticNode in m_staticNodes)
			{
				list.Add(((object)((NodeState)staticNode).NodeId).ToString());
			}
			foreach (BaseDataVariableState dynamicNode in m_dynamicNodes)
			{
				list.Add(((object)((NodeState)dynamicNode).NodeId).ToString());
			}
			return list;
		}

