				}
			}
			catch (Exception exception)
			{
				((CustomNodeManager2)this).m_logger.LogError(exception, "Unexpected error doing simulation #{Count}.", num);
			}
			finally
			{
				Interlocked.Decrement(ref m_simulationsRunning);
			}
		}

