	/// <summary>
	/// Base class for a batch of data
	/// </summary>
	public abstract class BatchBase
	{
		/// <summary>
		/// The unique Id of the batch
		/// </summary>
		public Guid Id { get; }

		/// <summary>
		/// The number of values in the batch
		/// </summary>
		public uint BatchSize { get; }

		/// <summary>
		/// The Id of the Monitored Item owning the batch
		/// </summary>
		public uint MonitoredItemId { get; }

		/// <summary>
		/// The batch has been persisted to disk
		/// </summary>
		public bool IsPersisted { get; protected set; }

		/// <summary>
		/// Restore is currently in progress in a background thread
		/// </summary>
		public bool RestoreInProgress { get; set; }

		/// <summary>
		/// Peristing is currently in progress in a background thread
		/// </summary>
		public bool PersistingInProgress { get; set; }

		/// <summary>
		/// Cancel this token to stop the persisting of the batch
		/// </summary>
		public CancellationTokenSource CancelBatchPersist { get; set; }

		protected BatchBase(uint batchSize, uint monitoredItemId)
		{
			BatchSize = batchSize;
			Id = Guid.NewGuid();
			IsPersisted = false;
			MonitoredItemId = monitoredItemId;
		}

		/// <summary>
		/// Marks the batch as persisted and removes the data from memory
		/// </summary>
		public abstract void SetPersisted();
	}
	/// <inheritdoc />
	public class BatchPersistor : IBatchPersistor
	{
		private static readonly JsonSerializerSettings s_settings;

		private static readonly string s_storage_path;

		private const string kBaseFilename = "_batch.txt";

		private readonly ConcurrentDictionary<Guid, BatchBase> m_batchesToRestore = new ConcurrentDictionary<Guid, BatchBase>();

		private readonly ConcurrentDictionary<Guid, BatchBase> m_batchesToPersist = new ConcurrentDictionary<Guid, BatchBase>();

		private readonly ILogger m_logger;

		private readonly ITelemetryContext m_telemetry;

		public BatchPersistor(ITelemetryContext telemetry)
		{
			m_logger = TelemetryExtensions.CreateLogger<DurableDataChangeMonitoredItemQueue>(telemetry);
			m_telemetry = telemetry;
		}

		/// <inheritdoc />
		public void RequestBatchPersist(BatchBase batch)
		{
			lock (batch)
			{
				if (batch.IsPersisted || batch.PersistingInProgress || batch.RestoreInProgress)
				{
					return;
				}
				batch.PersistingInProgress = true;
				if (m_batchesToPersist.TryAdd(batch.Id, batch))
				{
					Task.Run(delegate
					{
						PersistSynchronously(batch);
					}).ConfigureAwait(continueOnCapturedContext: false);
				}
			}
		}

		/// <inheritdoc />
		public void RequestBatchRestore(BatchBase batch)
		{
			lock (batch)
			{
				if (!batch.IsPersisted || batch.RestoreInProgress || batch.PersistingInProgress)
				{
					if (batch.PersistingInProgress)
					{
						batch.CancelBatchPersist?.Cancel();
					}
					return;
				}
				batch.RestoreInProgress = true;
				if (m_batchesToRestore.TryAdd(batch.Id, batch))
				{
					Task.Run(delegate
					{
						RestoreSynchronously(batch);
					}).ConfigureAwait(continueOnCapturedContext: false);
				}
			}
		}

		/// <inheritdoc />
		public void RestoreSynchronously(BatchBase batch)
		{
			string path = Path.Combine(s_storage_path, $"{batch.MonitoredItemId}_{batch.Id}{"_batch.txt"}");
			object obj = null;
			try
			{
				if (File.Exists(path))
				{
					obj = JsonConvert.DeserializeObject(File.ReadAllText(path), batch.GetType(), s_settings);
					File.Delete(path);
				}
			}
			catch (Exception exception)
			{
				m_logger.LogError(exception, "Failed to restore batch");
				batch.RestoreInProgress = false;
				m_batchesToRestore.TryRemove(batch.Id, out BatchBase _);
				return;
			}
			lock (batch)
			{
				if (batch is DataChangeBatch dataChangeBatch)
				{
					DataChangeBatch dataChangeBatch2 = obj as DataChangeBatch;
					dataChangeBatch.Restore(dataChangeBatch2.Values);
				}
				else if (batch is EventBatch eventBatch)
				{
					EventBatch eventBatch2 = obj as EventBatch;
					eventBatch.Restore(eventBatch2.Events);
				}
				m_batchesToRestore.TryRemove(batch.Id, out BatchBase _);
			}
		}

		/// <inheritdoc />
		public void PersistSynchronously(BatchBase batch)
		{
			using CancellationTokenSource cancellationTokenSource = new CancellationTokenSource();
			batch.CancelBatchPersist = cancellationTokenSource;
			try
			{
				string contents = JsonConvert.SerializeObject((object)batch, s_settings);
				if (!Directory.Exists(s_storage_path))
				{
					Directory.CreateDirectory(s_storage_path);
				}
				string path = Path.Combine(s_storage_path, $"{batch.MonitoredItemId}_{batch.Id}{"_batch.txt"}");
				File.WriteAllText(path, contents);
				BatchBase value;
				if (cancellationTokenSource.IsCancellationRequested)
				{
					File.Delete(path);
					value = batch;
					bool lockTaken = false;
					try
					{
						Monitor.Enter(value, ref lockTaken);
						batch.PersistingInProgress = false;
						batch.CancelBatchPersist = null;
					}
					finally
					{
						if (lockTaken)
						{
							Monitor.Exit(value);
						}
					}
				}
				else
				{
					value = batch;
					bool lockTaken = false;
					try
					{
						Monitor.Enter(value, ref lockTaken);
						batch.SetPersisted();
					}
					finally
					{
						if (lockTaken)
						{
							Monitor.Exit(value);
						}
					}
				}
				m_batchesToPersist.TryRemove(batch.Id, out value);
			}
			catch (Exception exception)
			{
				m_logger.LogWarning(exception, "Failed to store batch");
				lock (batch)
				{
					batch.PersistingInProgress = false;
					m_batchesToPersist.TryRemove(batch.Id, out BatchBase _);
					batch.CancelBatchPersist = null;
				}
			}
		}

		/// <inheritdoc />
		public void DeleteBatches(IEnumerable<uint> batchesToKeep)
		{
			try
			{
				if (!Directory.Exists(s_storage_path))
				{
					return;
				}
				DirectoryInfo directoryInfo = new DirectoryInfo(s_storage_path);
				Regex regex = new Regex(string.Join("|", batchesToKeep.Select((uint batch) => $"{batch}_.*{"_batch.txt"}$")), RegexOptions.Compiled);
				FileInfo[] files = directoryInfo.GetFiles();
				foreach (FileInfo fileInfo in files)
				{
					if (!regex.IsMatch(fileInfo.Name))
					{
						fileInfo.Delete();
					}
				}
			}
			catch (Exception exception)
			{
				m_logger.LogWarning(exception, "Failed to clean up batches");
			}
		}

		public void DeleteBatch(BatchBase batchToRemove)
		{
			try
			{
				if (!Directory.Exists(s_storage_path))
				{
					return;
				}
				DirectoryInfo directoryInfo = new DirectoryInfo(s_storage_path);
				Regex regex = new Regex($"{batchToRemove.MonitoredItemId}_.{batchToRemove.Id}._{"_batch.txt"}$", RegexOptions.Compiled);
				FileInfo[] files = directoryInfo.GetFiles();
				foreach (FileInfo fileInfo in files)
				{
					if (!regex.IsMatch(fileInfo.Name))
					{
						fileInfo.Delete();
						break;
					}
				}
			}
			catch (Exception exception)
			{
				m_logger.LogWarning(exception, "Failed to clean up single batch");
			}
		}

		static BatchPersistor()
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0005: Unknown result type (might be due to invalid IL or missing references)
			//IL_0011: Expected O, but got Unknown
			s_settings = new JsonSerializerSettings
			{
				TypeNameHandling = (TypeNameHandling)3
			};
			s_storage_path = Path.Combine(Environment.CurrentDirectory, "Durable Subscriptions", "Batches");
		}
