		/// <summary>
		/// Persist the queues of the monitored items with the provided ids
		/// Deletes the batches of all queues that are not in the list
		/// </summary>
		/// <param name="ids">the MonitoredItem ids of the queues to store</param>
		public void PersistQueues(IEnumerable<uint> ids, string baseDirectory)
		{
			string text = Path.Combine(baseDirectory, "Queues");
			if (!Directory.Exists(text))
			{
				Directory.CreateDirectory(text);
			}
			foreach (uint id in ids)
			{
				try
				{
					DurableEventMonitoredItemQueue value2;
					if (m_dataChangeQueues.TryGetValue(id, out DurableDataChangeMonitoredItemQueue value))
					{
						string contents = JsonConvert.SerializeObject((object)value.ToStorableQueue(), s_settings);
						File.WriteAllText(Path.Combine(text, id + "_queue.txt"), contents);
					}
					else if (m_eventQueues.TryGetValue(id, out value2))
					{
						string contents2 = JsonConvert.SerializeObject((object)value2.ToStorableQueue(), s_settings);
						File.WriteAllText(Path.Combine(text, id + "_queue.txt"), contents2);
					}
					else
					{
						m_logger.LogWarning("Failed to persist queue for monitored item with id {MonitoredItemId} as the queue was not known to the server", id);
					}
				}
				catch (Exception exception)
				{
					m_logger.LogWarning(exception, "Failed to persist queue for monitored item with id {MonitoredItemId}", id);
				}
			}
			m_batchPersistor.DeleteBatches(ids);
		}

