				string path = Path.Combine(baseDirectory, "Queues", id + "_queue.txt");
				if (!File.Exists(path))
				{
					return null;
				}
				string text = File.ReadAllText(path);
				File.Delete(path);
				StorableEventQueue queue = JsonConvert.DeserializeObject<StorableEventQueue>(text, s_settings);
				DurableEventMonitoredItemQueue queue2 = new DurableEventMonitoredItemQueue(queue, m_batchPersistor);
				m_eventQueues.AddOrUpdate(id, queue2, (uint _, DurableEventMonitoredItemQueue _) => queue2);
				return (IEventMonitoredItemQueue)(object)queue2;
			}
			catch (Exception exception)
			{
				m_logger.LogWarning(exception, "Failed to restore event change queue");
			}
			return null;
		}

