namespace Snet.Opc.ua.client
{
	/// <summary>
	/// OPC UA 客户端读取控制器，针对同一 OPC UA 服务器创建多个客户端会话并分配节点，
	/// 按服务器最大会话数拆分读取和订阅任务以提升吞吐量。
	/// </summary>
	public class OpcUaClientController
	{
		/// <summary>
		/// 读取节点集合
		/// </summary>
		private Address? Nodes;

		/// <summary>
		/// 订阅节点集合
		/// </summary>
		private Address? SubscriptionNodes;

		/// <summary>
		/// OPC UA 服务器基本连接参数
		/// </summary>
		private OpcUaClientData.Basics? ServerBasics;

		/// <summary>
		/// OPC UA 服务器支持的最大会话数量
		/// </summary>
		private int ServerMaxSession;

		/// <summary>
		/// 构造函数：初始化同一 OPC UA 服务器的客户端读取控制器。
		/// 此控制器通过将节点分配到多个会话来提升 OPC UA 客户端读取速度。
		/// </summary>
		/// <param name="ServerBasics">OPC UA 服务器基本连接参数</param>
		/// <param name="ServerMaxSession">OPC UA 服务器支持的最大会话数量</param>
		/// <param name="Nodes">读取节点集合</param>
		/// <param name="SubscriptionNodes">订阅节点集合（可选）</param>
		public OpcUaClientController(OpcUaClientData.Basics ServerBasics, int ServerMaxSession, Address Nodes, Address SubscriptionNodes = null)
		{
			this.Nodes = Nodes;
			this.ServerBasics = ServerBasics;
			this.ServerMaxSession = ServerMaxSession;
			this.SubscriptionNodes = SubscriptionNodes;
		}

		/// <summary>
		/// 根据最大会话数将节点平均分配到多个 OPC UA 客户端实例，
		/// 返回客户端实例与对应节点数据的映射字典。
		/// </summary>
		/// <returns>客户端实例到节点数据的线程安全映射字典</returns>
		public ConcurrentDictionary<OpcUaClientOperate, object> Get()
		{
			ConcurrentDictionary<OpcUaClientOperate, object> concurrentDictionary = new ConcurrentDictionary<OpcUaClientOperate, object>();
			if (SubscriptionNodes == null)
			{
				int num = ExtendMethod.ToInt((object)Math.Ceiling((float)Nodes.AddressArray.Count / (float)ServerMaxSession));
				Dictionary<int, Address> dictionary = OpcHelper.SplitList(Nodes, num);
				int num2 = 0;
				{
					foreach (KeyValuePair<int, Address> item3 in dictionary)
					{
