		/// <summary>
		/// 返回一组相对路径的节点id
		/// </summary>
		public static async Task<List<NodeId>> TranslateBrowsePaths(ISession session, NodeId startNodeId, NamespaceTable namespacesUris, CancellationToken cancellationToken, params string[] relativePaths)
		{
