				}
				bool flag = true;
				for (int j = 0; j < ((List<QualifiedName>)(object)val.BrowsePath).Count; j++)
				{
					if (((List<QualifiedName>)(object)val.BrowsePath)[j] != ((List<QualifiedName>)(object)browsePath)[j])
					{
