						break;
					}
				}
				if (flag)
				{
					return i;
				}
			}
			return -1;
		}

		/// <summary>
		///             访问级别属性的显示文本。
		/// </summary>
		private static string GetAccessLevelDisplayText(byte accessLevel)
		{
			StringBuilder stringBuilder = new StringBuilder();
			if (accessLevel == 0)
			{
				stringBuilder.Append("None");
			}
			if ((accessLevel & 1) == 1)
			{
				stringBuilder.Append("Read");
			}
			if ((accessLevel & 2) == 2)
			{
				if (stringBuilder.Length > 0)
				{
					stringBuilder.Append(" | ");
				}
				stringBuilder.Append("Write");
			}
			if ((accessLevel & 4) == 4)
			{
				if (stringBuilder.Length > 0)
				{
					stringBuilder.Append(" | ");
				}
				stringBuilder.Append("HistoryRead");
			}
			if ((accessLevel & 8) == 8)
			{
				if (stringBuilder.Length > 0)
				{
					stringBuilder.Append(" | ");
				}
				stringBuilder.Append("HistoryWrite");
			}
			if ((accessLevel & 0x10) == 16)
			{
				if (stringBuilder.Length > 0)
				{
					stringBuilder.Append(" | ");
				}
				stringBuilder.Append("SemanticChange");
			}
			return stringBuilder.ToString();
		}

		/// <summary>
		/// 事件通知属性的显示文本
		/// </summary>
		private static string GetEventNotifierDisplayText(byte eventNotifier)
		{
			StringBuilder stringBuilder = new StringBuilder();
			if (eventNotifier == 0)
			{
				stringBuilder.Append("None");
			}
			if ((eventNotifier & 1) == 1)
			{
				stringBuilder.Append("Subscribe");
			}
			if ((eventNotifier & 4) == 4)
			{
				if (stringBuilder.Length > 0)
				{
					stringBuilder.Append(" | ");
				}
				stringBuilder.Append("HistoryRead");
			}
			if ((eventNotifier & 8) == 8)
			{
				if (stringBuilder.Length > 0)
				{
					stringBuilder.Append(" | ");
				}
				stringBuilder.Append("HistoryWrite");
			}
			return stringBuilder.ToString();
		}

		private static string GetValueRankDisplayText(int valueRank)
		{
			return valueRank switch
			{
				-2 => "Any", 
				-1 => "Scalar", 
				-3 => "ScalarOrOneDimension", 
				0 => "OneOrMoreDimensions", 
				1 => "OneDimension", 
				2 => "TwoDimensions", 
				_ => valueRank.ToString(), 
			};
		}

		/// <summary>
		/// Create the continuation point collection from the browse result
		/// collection for the BrowseNext service.
		/// </summary>
		/// <param name="browseResultCollection">The browse result collection to use.</param>
		/// <returns>The collection of continuation points for the BrowseNext service.</returns>
		private static ByteStringCollection PrepareBrowseNext(BrowseResultCollection browseResultCollection)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0006: Expected O, but got Unknown
			ByteStringCollection val = new ByteStringCollection();
			foreach (BrowseResult item in (List<BrowseResult>)(object)browseResultCollection)
			{
				if (item.ContinuationPoint != null)
				{
					((List<byte[]>)(object)val).Add(item.ContinuationPoint);
				}
			}
			return val;
		}
	}
